quests[86367] = { id = 86367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larven zerstampfen" }
quests[86369] = { id = 86369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funkelndes Glück", description = "Ihr kommt gerade rechtzeitig, {class}.\n\n<Hüter Khubon zeigt Euch einen zerbrochenen Kristall.>\n\nDas ist ein gesplitterter Funke des Glücks. Wenn Ihr ein Reagenz wie dieses für Eure Ausrüstung verwendet, ist sie nicht mehr großartig, sondern grandios.\n\nAllerdings ist er ziemlich nutzlos, da es sich nur um ein Fragment handelt. Wenn Ihr bei Euren Abenteuern zufällig noch eins findet, bringt es mir. Wenn Ihr mir noch eins zeigt, schenke ich Euch dieses hier, damit Ihr daraus einen Funken des Glücks zusammenfügen könnt.", sourceObjective = "Sucht noch einen gesplitterten Funken des Glücks.", progress = "Habt Ihr einen gesplitterten Funken des Glücks gefunden? Ist das ein Ja? Nein?", completion = "Ausgezeichnet! Fügt die beiden gesplitterten Funken des Glücks zusammen, um einen mächtigen Funken des Glücks zu erschaffen. Ihr könnt mit Eurer Handwerksfertigkeit jederzeit selbst weitere kombinieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[86372] = { id = 86372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt den Ödnisbewohnern ihren Platz" }
quests[86388] = { id = 86388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark - Template" }
quests[86390] = { id = 86390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfogger-Nervensäge" }
quests[86391] = { id = 86391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir holen uns unsere Macht zurück" }
quests[86392] = { id = 86392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanz mit dem Fuchs", description = "Eure Bemühungen, der Matriarchin das Jagen beizubringen, scheinen zu effektiv gewesen zu sein. Mehrere Wächter der Mittler wurden vor Kurzem angegriffen.\n\nDa Ihr dieses Problem verursacht habt, müsst Ihr es auch lösen. Besiegt die Dornschweifmatriarchin im Kampf. Die restlichen Dornschweife werden sich zurückziehen, nachdem ihre Anführerin gedemütigt wurde.", sourceObjective = "Fordert die Dornschweifmatriarchin heraus und besiegt sie.", completion = "Ich wusste, dass Ihr diese Situation effektiv meistern würdet. Aber ich hätte nicht gedacht, dass es so viel Spaß machen würde, Euch dabei zuzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86395] = { id = 86395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes zurückstehlen" }
quests[86396] = { id = 86396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugstein, Flugstein, jeder muss entdeckt sein", description = "Es ist so aufregend, in Valdrakken zu sein! Cuzolth und ich waren noch nie hier. Und es bietet wirklich alles, was wir uns erhofft hatten. Einige der anderen haben sich sogar vorgestellt. Sie haben uns tatsächlich für unsere Forschung zu den Flugsteinen und Wappen gedankt! Das ist der Traum jedes Forscherherzens!\n\nDeshalb brauche ich noch einmal Eure Hilfe. Könntet Ihr einige Flugsteine und ein neues Teil Abenteuerausrüstung auftreiben? Damit könnt Ihr dann zu Cuzolth kommen, um es aufzuwerten. Das würde uns wirklich helfen, unsere neue Position hier zu festigen.", sourceObjective = "Besorgt 50 Flugsteine, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge meistert, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Cuzolth und wertet einen Ausrüstungsgegenstand aus Saison 4 unter Einsatz von Flugsteinen auf.", progress = "Es hat keine Eile. Aber vielleicht beeilt Ihr Euch trotzdem ein wenig...", completion = "Hallo! Ich wusste, Ihr würdet mir mehr Tapferkeitssteine bringen. Hier habt Ihr eine Kleinigkeit für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86399] = { id = 86399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckte Wappen, unbegrenzte Möglichkeiten", description = "Eure Hilfe ist immer willkommen, und jetzt könnt Ihr Eure niedrigstufige Ausrüstung gleich hier aufwerten.\n\nAllerdings wisst Ihr vermutlich schon, dass Flugsteine auch ihre Grenzen haben. Um mächtige Abenteuerausrüstung aufzuwerten, braucht Ihr erweckte Wappen. Genau wie Flugsteine könnt Ihr diese Wappen bei vielen verschiedenen Aktivitäten erlangen. Erweckte Wappen gibt es in vier Stufen: je gefährlicher die Aufgabe, desto höher die Stufe des Wappens, das Ihr dafür bekommt.\n\nBringt mir doch 15 erweckte Wappen des Welpen, und wir können Euch helfen, Eure Ausrüstung weiter aufzuwerten.", sourceObjective = "Besorgt 15 erweckte Wappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Valdrakken zurück.", progress = "Wenn Ihr Schwierigkeiten habt, verwitterte Lorenhallwappen zu finden, könnt Ihr in Khaz Algar oder diesen unterirdischen Gebieten, einschließlich Lorenhall, nach versteckten Schätzen suchen. Da gibt es freilich jede Menge von diesen Schätzen!", completion = "Wunderbar. Ich freue mich schon, dass Ihr noch mächtiger werdet! Und natürlich, dass meine Forschung weiter vorangetrieben wird. Aber ja, machen wir Euch noch mächtiger!", sourceObjectiveStatus = "unverified-source-field" }
quests[86401] = { id = 86401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckte Wappen, unbegrenzte Möglichkeiten", description = "Eure Hilfe ist immer willkommen, und jetzt könnt Ihr Eure niedrigstufige Ausrüstung gleich hier aufwerten.\n\nAllerdings wisst Ihr vermutlich schon, dass Flugsteine auch ihre Grenzen haben. Um mächtige Abenteuerausrüstung aufzuwerten, braucht Ihr erweckte Wappen. Genau wie Flugsteine könnt Ihr diese Wappen bei vielen verschiedenen Aktivitäten erlangen. Erweckte Wappen gibt es in vier Stufen: je gefährlicher die Aufgabe, desto höher die Stufe des Wappens, das Ihr dafür bekommt.\n\nBringt mir doch 15 erweckte Wappen des Welpen, und wir können Euch helfen, Eure Ausrüstung weiter aufzuwerten.", sourceObjective = "Besorgt 15 erweckte Wappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Valdrakken zurück.", progress = "Wenn Ihr diese geschnitzten Lorenhallwappen verliert, findet Ihr bei mächtigen Kreaturen um Khaz Algar weitere. Es soll ja die verschiedensten geben!", completion = "Beeindruckend, oder?\n\nIch bin stolz darauf, wie viel ich über die Wappen gelernt habe. Vor nur zwei Jahren war Transmutation noch ein Traum und jetzt ist es beinahe meine Alltagsarbeit. Nun, ein Teil meiner Alltagsarbeit. Nun, Teil meiner Alltagsarbeit, wenn Ihr die Hilfe benötigt. Cuzolth und ich sind Euch für Eure Unterstützung wirklich dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[86408] = { id = 86408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Loch in der Wand", description = "Als ich nach etwas Sicherheit suchte, hätte ich nie gedacht, dass ich <einen echten Helden/eine echte Heldin> finden würde. Kein Wunder, dass Euch Euer Ruf vorauseilt. Ihr helft gerne, stimmt's?\n\nPasst auf, ich will nicht zu rührselig klingen, aber... Was Ihr für alle hier getan habt...\n\n<Mama Kaera schüttelt den Kopf und reißt sich zusammen.>\n\nWie auch immer. Abgemacht ist abgemacht. Tragt Euch im Protokollbuch da drüben ein, dann seid Ihr offiziell <Bürger/Bürgerin> von Fassgrund. Ich würde sagen, das habt Ihr definitiv verdient.", sourceObjective = "Untersucht das Protokollbuch der Fassgrund-Apartments.", completion = "<Mit Eurer Unterschrift im Register erhaltet Ihr uneingeschränktes Wohnrecht im obersten Stockwerk der Fassgrund Apartments.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86409] = { id = 86409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über die Klippen pirschen" }
