quests[86414] = { id = 86414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnoschrotter 9000" }
quests[86417] = { id = 86417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereitschaft", description = "Wir haben getan, was wir hier tun konnten, {name}. Jetzt müssen wir einfach hoffen, dass es reicht.\n\nVielleicht hat Gazlowe einen Plan. Vielleicht sind wir jetzt so weit, uns Gallywix zu stellen. Lasst uns die nächsten Schritte ausformulieren. Ab und an genieße ich ein bisschen Formuliererei.", sourceObjective = "Erkundigt Euch bei Grimla, was als Nächstes zu tun ist.", completion = "Ich hab einen ganzen Haufen Goblins, die ein Wörtchen mit der Verwaltung zu wechseln haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[86418] = { id = 86418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisches Handtuch?" }
