quests[86447] = { id = 86447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingerangriff: Biokuppel: Primus" }
quests[86448] = { id = 86448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles fügt sich zusammen", description = "<Elise Sternensucher sollte in der Lage sein, diese Beutereste des Tiefenforschers wieder zusammenzuführen.>", sourceObjective = "Kauft eine Beute des Tiefenforschers von Elise Sternensucher in Dornogal.", sourceObjectiveStatus = "unverified-source-field" }
quests[86456] = { id = 86456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klagelied einer stillen Welt", description = "<Der Kristall, den Ihr haltet, vibriert leicht in Eurer Hand. Die Energie, die er ausstrahlt, gibt Euch das Gefühl, er würde Eure Hand halten. Als würde er die Hand nach Euch ausstrecken und niemals loslassen wollen... als würde er wollen, dass Ihr sie haltet und ihn zurück in Sicherheit bringt. Ihr hört ein leises Lied im Hinterkopf - ein Lied der Furcht, Verwirrung und des Verlangens, zu leben.\n\nVielleicht weiß Ve'nari mehr darüber?>", sourceObjective = "Bringt den verdunkelten Kristall zu Ve'nari in der Oase.", progress = "Ich muss mich um eine weitere Krise in meinen Biokuppeln kümmern, {name}. Macht es kurz oder tretet beiseite.", completion = "<Ve'nari hält inne, als wäre sie von einem Lied abgelenkt.>\n\nWo habt Ihr diesen Kristall gefunden? Ich höre ihn singen... in meinem Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[86457] = { id = 86457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiegelied der Hoffnung", description = "{name}, wisst Ihr, was das ist?\n\nWenn ich richtig liege, dann ist dieser Kristall die Essenz meiner Welt, K'aresh. Ich habe viel von meinem Kapital dafür aufgewendet, über das Biokuppelprojekt einen Funken von K'aresh zu bewahren. Doch das...\n\nIch möchte keine voreiligen Schlüsse ziehen, bevor ich meine Annahme bestätigen kann.\n\nLegt den Splitter ab und lasst uns sehen, was wir herausfinden können.", sourceObjective = "Platziert den verdunkelten Kristall.", progress = "Wenn dieser Kristall ist, was ich vermute, dann haben wir eine neue Hoffnung für die Rettung K'areshs gefunden.", completion = "Ich kann es nicht fassen! Ich...\n\n<Ve'nari verstummt.>\n\n{name}, was Ihr gefunden habt, wird die Zukunft von K'aresh verändern.\n\nDie Zukunft meines Volkes.", sourceObjectiveStatus = "unverified-source-field" }
quests[86458] = { id = 86458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Lied für unsere Zukunft", description = "Es gibt eine Stätte, die Biokuppel Al'dani, die ich verborgen gehalten habe. Sie wurde auf den Überresten einer unserer heiligsten Stätten mit einer mächtigen Verbindung zu K'aresh errichtet. Sie ist die Stätte des größten Erfolgs unseres Projekts. Sie ist der Ort, an den wir die Essenz der Weltenseele bringen können, damit sie überleben kann.\n\nEs ist außerdem die Biokuppel, wo die Seelenschreiberin und die Ödnisbewohner angreifen.\n\nMacht ein letztes Mal den Weg für mich frei, {name}. Damit K'aresh überleben kann, müssen sowohl die Kuppel als auch die Seelenschreiberin intakt bleiben.", sourceObjective = "Besiegt die Seelenschreiberin in der Biokuppel Al'dani.", progress = "Wir müssen die Seelenschreiberin zur Vernunft bringen. Wir müssen verhindern, dass ihr Schwur gegenüber Salhadaar K'areshs Untergang wird.", completion = "Was sich hier zugetragen hat, wird noch jahrelang nachhallen. Dieser Wandel wird nicht innerhalb eines Tages, einer Woche oder sogar mehrerer Monate stattfinden. Doch mit neu entfachter Hoffnung werden wir dorthin gelangen und wiedervereint sein.\n\nIhr habt uns alle gerettet, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[86461] = { id = 86461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriosität: Kampf", description = "<Als Ihr die Kuriosität in Händen haltet, seht Ihr, dass sie leuchtet. Das muss Bedeutung haben. Die Forscherliga wäre sicher interessiert.>", sourceObjective = "Setzt eine Kampfkuriosität ein und rüstet Brann Bronzebart damit aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[86462] = { id = 86462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antike Kuriosität: Unterstützung", description = "<Als Ihr die Kuriosität in Händen haltet, seht Ihr, dass sie leuchtet. Das muss Bedeutung haben. Die Forscherliga wäre sicher interessiert.>", sourceObjective = "Setzt eine Unterstützungskuriosität ein und rüstet Brann Bronzebart damit aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[86464] = { id = 86464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingerangriff: Das Atrium" }
quests[86465] = { id = 86465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingerangriff: Tazavesh" }
quests[86469] = { id = 86469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour durch Stromgarde", sourceObjective = "Kümmert Euch um 1 Unterstützer von Marran in Stromgarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[86470] = { id = 86470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerins Version", description = "Ich brauche jemanden, der den Leuten in der Stadt diese Anfragen zustellt. Wir sind unterbesetzt, und ich bin noch nicht dazu gekommen, diese hier zu verteilen.\n\nAls <mein neuester Stellvertreter/meine neueste Stellvertreterin> liegt diese Verantwortung nun bei Euch!\n\nDie meisten davon sind einfach und unkompliziert. Anfragen nach Vorräten und dergleichen für die Stromgarder Armee.\n\nJoseph ist eine andere Sache. Er hetzt die Bevölkerung mit aufrührerischer Rhetorik auf. Er muss damit aufhören, oder wir müssen ihn verhaften. Wir können uns im Moment keinen weiteren Aufruhr leisten.", sourceObjective = "Stellt Bräusteins Anfragen den Leuten in Stromgarde zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[86476] = { id = 86476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Frühe Kartellkriege" }
quests[86477] = { id = 86477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseelenerinnerung: Kaja'mitkontakt" }
