quests[86481] = { id = 86481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[86482] = { id = 86482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rettungsanker", description = "<Der Schnappdrache bewegt sich kaum, als Ihr Euch nähert. Er ist eindeutig schwach und scheint viel kleiner zu sein, als er es sein sollte.\n\nVielleicht hat Zexel Fingerschnipp etwas zu verkaufen, das ihm wieder auf die Beine helfen könnte?>", sourceObjective = "Sprecht mit Zexel Fingerschnipp.", progress = "<Der kleine Schnappdrache schaut Euch müde und mit trüben Augen an.>", completion = "<Der kleine Schnappdrache stürzt sich gierig auf den Leckerbissen. Sowohl das Fleisch als auch die koffeinhaltige Kaja'Cola, in der das Fleisch getränkt war, scheinen ihm Energie zu geben.\n\nEr schaut Euch mit Dankbarkeit in seinen Augen an.\n\nEr wird sich an Euch erinnern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86483] = { id = 86483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dann mal schnipp schnapp", description = "<Der Schnappdrache scheint Euch zu erkennen, als Ihr Euch nähert, denn seine Ohrlamellen wackeln erwartungsvoll.\n\nEr ist über Nacht nicht nur größer geworden, sondern seine Schuppen haben auch eine algengrüne Farbe angenommen, ähnlich wie das Fleisch aus der Kaja'Cola, mit dem Ihr ihn gefüttert habt.\n\nZwischen seinen Krallen liegen Fleischrationen, die er von den Angreifern in der Nähe gestohlen hat. Der Schnappdrache schaut Euch hoffnungsvoll an.\n\nVielleicht könnt Ihr ihm weitere Fleischrationen bringen, wenn Ihr die Eindringlinge auf der Insel tötet.", sourceObjective = "Findet 5 Fleischrationen bei den einfallenden Truppen: Piraten, Naga oder Vrykul.", progress = "<Der Schnappdrache scharrt mit den Pfoten auf dem Boden und schaut Euch dann erwartungsvoll an. Seine Augen funkeln vor Intelligenz.>", completion = "<Der Schnappdrache wird munter, als Ihr Euch nähert, und schnuppert, als wolle er prüfen, ob Ihr ihm etwas zu essen mitgebracht habt.\n\nSobald er die Rationen in Eurer Hand sieht, schnappt er in Erwartung einer leckeren Mahlzeit zu.\n\nMit vollem Bauch legt er sich zur Ruhe, schaut aber weiter zu Euch hinauf, als würde er hoffen, dass Ihr morgen wiederkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86484] = { id = 86484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Temperament eines Unwetters", description = "<Der Schnappdrache scheint Euch zu erkennen, als Ihr Euch nähert, denn seine Ohrlamellen wackeln erwartungsvoll.\n\nEr ist über Nacht nicht nur größer geworden, sondern auch seine Schuppen haben sich durch das Fleisch, mit dem Ihr ihn gestern gefüttert habt, verfärbt.\n\nZwischen seinen Krallen liegen die Reste eines Meerestieres aus dem letzten Meereszornunwetter. Der Schnappdrache schaut Euch hoffnungsvoll an.\n\nVielleicht könnt Ihr ihm mehr Fleisch bringen, wenn Ihr Euch in das Meereszornunwetter begebt und dort Kreaturen erlegt.>", sourceObjective = "Sprecht mit Susi Bolzschraub, um Euch in das Meereszornunwetter zu begeben, und tötet Kreaturen, um sturmerfülltes eigenartiges Fleisch zu erhalten.", progress = "<Der Schnappdrache scharrt mit den Pfoten auf dem Boden und schaut Euch dann erwartungsvoll an. Seine Augen funkeln vor Intelligenz und Hunger.>", completion = "<Beim Anblick des Fleisches, das Ihr ihm gebracht habt, schnappt der Schnappdrache hungrig zu. Als Ihr das Fleisch ablegt, stürzt er sich darauf und frisst es in Sekundenschnelle auf.\n\nEr schaut mit neuem Respekt zu Euch auf, denn schließlich habt Ihr mächtige Kreaturen erlegt, um ihm dieses Mahl zu bringen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86485] = { id = 86485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein treuer Freund", description = "<Der Schnappdrache scheint Euch zu erkennen, als Ihr Euch nähert, denn seine Ohrlamellen wackeln vor Erwartung.\n\nEr steht mit seinem massiven, geschmeidigen Körper als ausgewachsener Drache vor Euch. Er starrt Euch an und klappert leise mit seinem massiven Kiefer, als ob er etwas beschließen würde.\n\nEr scheint darauf zu warten, dass Ihr den ersten Schritt tut.>", sourceObjective = "Sprecht mit dem Schnappdrachen.", progress = "<Der Schnappdrache zischt und wackelt mit seinen Ohrlamellen. Er wirkt beeindruckt.>", completion = "<Der Schnappdrache verbeugt sich vor Euch als Zeichen des Respekts. Er scheint dankbar für alles zu sein, was Ihr für ihn getan habt.\n\nEr wird Euch jetzt als Reiter akzeptieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86486] = { id = 86486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungriger, hungriger Schnappdrache", description = "<Der Schnappdrache scheint Euch zu erkennen, als Ihr Euch nähert, denn seine Ohrlamellen wackeln vor Erwartung.\n\nEr ist wieder hungrig und schaut Euch erwartungsvoll an. Er scheint Fleisch zu wollen und scheinbar ist es ihm egal, woher es kommt.>", sourceObjective = "Sammelt 8 eigenartige Fleischhappen, indem Ihr die Kreaturen auf der Sireneninsel tötet.", progress = "<Der Schnappdrache regt sich, als Ihr Euch nähert, und seine unnatürlich intelligenten Augen mustern Euch.\n\nOffensichtlich hofft er, dass Ihr ihm eine Mahlzeit mitgebracht habt.>", completion = "<Der Schnappdrache wartet kaum ab, bis Ihr die Rationen fallen lasst, bevor er sie gierig verschlingt. Offensichtlich war er hungrig.\n\nAls er fertig ist, sieht er zufrieden und schläfrig aus. Euch ist klar, dass das nicht lange so bleiben wird. Vielleicht solltet Ihr morgen noch einmal versuchen, ihn zu füttern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[86491] = { id = 86491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchtriebene Duos! Es ist soweit!", description = "Hallo, Kampfesfreunde. Die miesesten Bösewichte haben sich zusammengefunden und sind auf Rache aus! Sie sind zurück, dieses Mal als Durchtriebene Duos!\n\nTrefft mich am Fuße des Rivalentors in Dornogal und meldet Euch an, um Euch den Durchtriebenen Duos zu stellen. Legt diesen Bossen ein weiteres Mal das Handwerk. Erlebt den Kampf aufs Neue!\n\n- Vinnie Naschkatze", sourceObjective = "Sprecht mit Vinnie Naschkatze in der Nähe des Rivalentors in Dornogal.", completion = "Das seid Ihr ja. Lasst uns ordentlich Kohle scheffeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[86493] = { id = 86493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - 1st", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[86494] = { id = 86494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Timewalking \"Heroic\" Random - Nth", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[86495] = { id = 86495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reshiiband", description = "Während des Verschlingerkriegs wurde ich Zeuge der schrecklichen Auswirkungen, die die Gegenwart des alles Verschlingenden nach sich zieht. Ein sterbliches Wesen wird sich ihm bei der Manaschmiede nicht nähern können. Er ist die Entropie des Endes und Ihr nur ein Haufen Fleisch.\n\nXal'atath kennt Rituale aus den Großen Dunklen Weiten. Mit der Kraft der Reshiibänder konnte sie die K'areshi derart verwandeln, dass sie Dimensius standhalten konnten.\n\nAlleria wird dieser Plan nicht gefallen. Ihr müsst sie überzeugen!", sourceObjective = "Überzeugt Alleria, das Ritual der Verwandlung an Euch durchzuführen.", progress = "Jeder Moment, den wir diskutieren oder streiten, bringt uns Dimensius' Rückkehr einen Schritt näher.", completion = "Sie war einverstanden?\n\nAlleria hört auf Euch, Champion. Ihr seid unsere Erlösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[86496] = { id = 86496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Auftragsarbeit", description = "<Bargus hält einen winzigen, goldenen Kristallsplitter hoch.>\n\nSo wie die strahlenden Überbleibsel, die die Arathi in Heilsturz gefunden haben, scheint auch der Sirenenkristall Einfluss auf die geologische Zusammensetzung der Insel zu haben.\n\nIm Gegensatz zu unseren Goblinkollegen sollten wir lieber die Finger von den größeren Splittern auf der Insel lassen, um die instabilen Höhlen unter uns nicht zu belasten oder die Arathi zu beleidigen.\n\nAber diese winzigen Splitter sind eine Untersuchung wert.\n\nBringt mir eine ordentliche Portion davon. Nur... zu rein experimentellen Zwecken.", sourceObjective = "Sammelt 50 Kristallsplittertrümmer.\n\nIhr könnt Kristallsplittertrümmer nur während eines Meereszornunwetters von Kreaturen auf der Sireneninsel erbeuten.", progress = "Habt Ihr weitere Splitter des Sirenenkristalls gefunden? Ich glaube, ich könnte damit etwas Nützliches herstellen.", completion = "<Bargus verteilt die Trümmer auf seinem Amboss und nickt bestimmt.>\n\nIch werde sofort mit der Erforschung dieses neuen Materials beginnen! Habt vielen Dank, {name}.\n\nIhr könnt Euch gerne an meinen neuesten Waffen bedienen.\n\nSie sollten zwar eigentlich an die Erweckungsmaschine geliefert werden, aber da sie aussehen, als wären sie Euch wie auf den Leib geschneidert, dürft Ihr meine Arbeit gerne erproben.", sourceObjectiveStatus = "unverified-source-field" }
quests[86503] = { id = 86503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sind die Durchtriebenen Duos?", description = "Gute Frage! So könnt Ihr es herausfinden: Sprecht mit Xyggie Marou und meldet Euch für einen Kampf gegen die Durchtriebenen Duos an.\n\nUnd weil Ihr <ein Anfänger/eine Anfängerin> seid, bekommt Ihr eine Liste von \"durchtriebenen\" Aufgaben, die Ihr dabei erledigen könnt!\n\nViel Glück! Vielleicht sieht man sich ja auf der anderen Seite.", sourceObjective = "Besiegt die Durchtriebenen Duos, während Ihr Vinnies \"durchtriebene\" Aufgabe erledigt, und sprecht anschließend mit Vinnie Naschkatze.", progress = "Sprecht mit Xyggie Marou, erledigt meine Aufgaben und besiegt diese Durchtriebenen Duos!", completion = "Ich habe Euren Kampf gesehen. Nicht schlecht. Hier ist Euer Preis. War mir eine Ehre.\n\nMeldet Euch gerne wieder an. Nächstes Mal wette ich lieber nicht gegen Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[86535] = { id = 86535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testlauf", description = "Hey, wollt Ihr etwas Knete machen?\n\nWir haben eine Abmachung mit den Irdenen ausgehandelt, in deren Zuge wir einen Teleporter in Dornogal bauen. Wir bekommen so viel Tourismus, wie wir verkraften können, und sie dürfen sich die besten gesprungenen, zersplitterten oder sonst unverkäufliche Edelsteine aussuchen, die Lorenhalls Juweliere zu bieten haben.\n\nIch habe dieses Ende gerade eingerichtet, konnte es aber noch nicht ausprobieren. Möchtet Ihr ihn ausprobieren? Wenn Ihr auf der anderen Seite herauskommt, wird meine Kollegin Kenzi Euch bezahlen.\n\nSagen wir, das stellt einen verbalen Haftungsausschluss das, ja?", sourceObjective = "Verwendet den Teleporter, um von Lorenhall nach Dornogal zu reisen.", completion = "Woah! Ich dachte, Rostol würde eine Rennmaus oder eine Dose Pfirsiche oder sowas durchschicken, um den neuen Teleporter zu testen, keine lebende Person!\n\nAber Ihr seid nur leicht angeschmort! Fantastisch.\n\nIch sag Euch was. Dafür, dass Ihr uns den Gefallen getan und gleichzeitig so wenig Rücksicht auf Euer eigenes Wohlergehen genommen habt, dürft Ihr die Teleporter jederzeit kostenlos verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[86555] = { id = 86555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wohltäter von Lorenhall", sourceObjective = "Danke für Eure Hilfe, Lorenhall wieder auf die richtige Spur zu bringen. Hier habt Ihr eine Kleinigkeit für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86556] = { id = 86556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verwüstete Reise durch die Zeit", description = "Der Stern des Zerstörers bedeckt das Land mit seinem durchdringenden Licht, sodass sich selbst die Geister in die Schatten zurückziehen. Dieser Stern ist wie kein anderer am Himmel. Er offenbart selbst die Schwächen der furchtlosesten Helden. Solange er am Himmel steht, können sich neue Pfade zu fernen Orten oder sogar Zeiten eröffnen. Die Gelehrten sind ratlos, was die Natur dieses Zeichens betrifft, doch das Glück belohnt bekanntlich die Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86560] = { id = 86560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verschleierte Reise durch die Zeit", description = "Der verschleierte Stern flackert über dem Land und sein blinkendes Licht lässt einen unheimlichen Nebel über das Land ziehen. Dieser Stern und der Nebel werfen tiefe Schatten auf das Land und verbergen seine Geheimnisse und Gefahren. Unter seinem Einfluss eröffnen sich neue Wege zu weit entfernten Orten und sogar in weit entfernte Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Omens vollends zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", progress = "Ich sehe, dass Ihr dem verschleierten Stern auf dem von ihm aufgezeigten Weg folgen werdet.", completion = "Ah, {name}. Ihr seid zurück. Ein schwerer Nebel hängt Euch an.", sourceObjectiveStatus = "unverified-source-field" }
quests[86563] = { id = 86563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wilde Reise durch die Zeit", description = "Der brutale Stern wirft sein Licht auf das Land und droht, alle, die sich ihm in den Weg stellen, niederzutrampeln. Dieser Stern ist vieles: urzeitlich, heftig und edel. Unter seinem Einfluss eröffnen sich neue Wege zu weit entfernten Orten und sogar in weit entfernte Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Omens vollends zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", progress = "Ich sehe, dass Ihr dem brutalen Stern auf dem von ihm aufgezeigten Weg folgen werdet.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86564] = { id = 86564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine teuflische Reise durch die Zeit", description = "Ein verderbender Stern wirft sein Licht auf das Land und bedroht alle mit brennendem Vergessen. Der Stern verrät diejenigen, die das Licht suchen, denn sein rotes Glühen verdunkelt mehr, als dass er enthüllt.\n\nUnter seinem Einfluss eröffnen sich neue Wege zu weit entfernten Orten und sogar in weit entfernte Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Omens vollends zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Eine teuflische Aura umgibt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[86575] = { id = 86575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenrumba", description = "Dieser Schrott kommt wie gerufen. Und jetzt, wo diese widerlichen Blutschmauser mir nicht mehr auf die Pelle rücken, kann ich diese Bots offiziell fertigstellen.\n\nWieso überbringt Ihr Benny nicht die guten Nachrichten, während ich hier den Rest abwickle?\n\nIch bin mir sicher, dass er sie unverzüglich einsetzen wollen wird.", sourceObjective = "Kehrt zu Benny Gänsesprenger vor der Höhle in den Schallenden Tiefen zurück.", completion = "Ihr habt Trixxie dabei geholfen, die Bots herzurichten?\n\nAußerordentlich großartig, {name}!\n\nDann muss ich mir keine Sorgen mehr ums Personal machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86584] = { id = 86584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigender Pflichturlaub" }
quests[86587] = { id = 86587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Maldraxxus", description = "Der Himmel von K'aresh war einst voll von Rochen. Ihre leerenberührten Abkömmlinge sind zwar im Himmel außerhalb der Oase zu finden, aber es gibt keine überlebenden Exemplare, die nicht leerenberührt wurden.\n\nAllerdings kenne ich einen Ort, an dem wir ähnliche Kreaturen beschaffen können, um dieselbe Nische im Ökosystem auszufüllen: Maldraxxus in den Schattenlanden. Geht durch mein Portal und findet die Kreaturen für mich.", sourceObjective = "Reist nach Maldraxxus in den Schattenlanden und beschafft Rochen für Ve'nari.", completion = "Ve'nari hat Euch geschickt? Wie wundervoll! Ich war gerade auf der Suche nach etwas Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[86588] = { id = 86588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualmord", description = "Die hiesigen Ritualisten bereiten den Nekrorochen Probleme. Genauer gesagt, Seuchenprobleme.\n\nWenn Ihr sie tötet, sollte sich die Lage für die Nekrorochen entspannen.", sourceObjective = "Tötet 13 morbide Ritualisten.", completion = "Was für ein guter Lehrling Ihr seid.\n\nSehr gut darin, Anweisungen zu befolgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[86589] = { id = 86589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest und Pein, der Arzt bleibt daheim", description = "Diese Ritualisten haben eine neue Seuche an unseren armen Nekrorochen getestet. Das ist abscheulich... Das ist MEIN Job!\n\nBringt mir ein paar Proben toter Rochen. Ich sollte daraus ein Heilmittel für diejenigen herstellen können, die noch am Leben sind.", sourceObjective = "Sammelt 6 Seuchenproben von den toten pestbringenden Nekrorochen.", progress = "Habt Ihr die Proben für mich?", completion = "Pah! Das ist stümperhaft. Ich habe schon Schleime gesehen, die bessere Seuchen ausgespuckt haben! Natürlich habe ich diese Schleime selbst erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86590] = { id = 86590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrling wider Willen", description = "Gut, dass Ihr hier seid, Lehrling! Ich bin gekommen, um die Essenzen der hiesigen Grolle zu sammeln. Sie eignet sich wunderbar, um einer Seuche diese gewisse Extrawürze zu verleihen.\n\nAber da Ihr nun hier seid, könnt Ihr das für mich übernehmen! Was für eine großartige Lerngelegenheit für Euch!", sourceObjective = "Sammelt 15 Grollessenzen.", progress = "Und? Habt Ihr die Essenzen gesammelt?", completion = "Was für ein ausgezeichneter Lehrling Ihr seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[86591] = { id = 86591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stümperhafte Seuchenschöpfung", description = "Das ist Vorax' Werk. Er war einst mein Lehrling, genauso wie Ihr!\n\nEr versucht meine Arbeit zu replizieren? Schmeichelnd, aber schlampig. Ich werde an einer Lösung für Euch arbeiten, Lehrling, während Ihr an einer Lösung für ihn arbeitet.", sourceObjective = "Tötet Großritualist Vorax.", progress = "Ist die Tat vollbracht?", completion = "Ach herrje. Ich hätte Euch bitten sollen, seine Überreste mitzubringen. Die hätte ich gut gebrauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[86592] = { id = 86592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impftermin", description = "Wenn diese Rochen reisen sollen, sollten wir sie zuerst immunisieren.\n\nWas für eine gute Gelegenheit für Euch, Lehrling, etwas über die Verabreichung von Antiseuche zu lernen! Das kommt hier nicht sehr oft vor.", sourceObjective = "Immunisiert 5 beruhigte Nekrorochen.", progress = "Habt Ihr die Nekrorochen geimpft?", completion = "Ich bin froh, dass Ihr hier wart, Lehrling. Ich finde es recht beunruhigend, alle Seuchen aus einer Kreatur zu entfernen. Fühlt sich sehr ungesund an.", sourceObjectiveStatus = "unverified-source-field" }
quests[86593] = { id = 86593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Oase", description = "Ich nehme an, Ihr werdet jetzt zurückkehren?\n\nEs war mir eine wahre Freude, mit Euch zu arbeiten, Lehrling. Ich hoffe, wir sehen uns bald wieder. Es wird dann einige neue Experimente geben, bei denen Ihr mir helfen könnt. Bitte kümmert Euch gut um die Nekrorochen! Ich hoffe, sie fühlen sich in ihrem neuen Zuhause wohl.", sourceObjective = "Reist zur Oase von K'aresh.", completion = "Gut gemacht. Ich habe die Nekrorochen gemäß unserer Quarantänevorschriften ins Atrium überführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86594] = { id = 86594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschmecker mit Flossen", description = "Wir versuchen herauszufinden, was diese Rochen fressen.\n\nIch habe eine Auswahl zusammengestellt. Könnt Ihr sie verteilen? Ich werde die Reaktionen beobachten.", sourceObjective = "Platziert 3 Nahrungsmittel.", progress = "Fütterungszeit! Kümmert Euch darum.", completion = "Sie fressen anscheinend so ziemlich alles. Allesfresser, das ist durchaus praktisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[86595] = { id = 86595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinemachen im Reich der Rochen", description = "Scheint, als würden diese Rochen beim Umhergleiten eine schmierige Masse absondern. Die gerinnt und macht ganz schön Dreck!\n\nVe'nari hat dieses hilfreiche Sauggerät rübergeschickt. Könntet Ihr damit reinemachen, während Ihr Eure Runden dreht?", sourceObjective = "Beseitigt 18 geronnene Klumpen im Atrium.", completion = "Dieser Schlamm ist zäh. Danke, dass Ihr Euch darum gekümmert habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[86601] = { id = 86601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volltreffer im Rochenhimmel", description = "Markiert die Nekrorochen mit diesen Pfeilen, die Standort und Gesundheit überwachen. Außerdem injizieren sie ein Schmerzmittel, sodass die Nekrorochen es nicht einmal bemerken.\n\nDiese Mittler haben wirklich unglaubliche Erfindungen!", sourceObjective = "Markiert 5 neugierige Nekrorochen.", completion = "Gute Arbeit beim Markieren der Nekrorochen. So können wir sie besser im Blick behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[86602] = { id = 86602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visite bei den Tieren", description = "Ihr sagtet, Euer Freund hätte diese Nekrorochen entseucht, aber wir müssen nachschauen, ob sie die anderen Tiere nicht mit noch etwas anderem anstecken.\n\nKönnt Ihr ein paar Proben sammeln gehen, damit wir sie auf Probleme überprüfen können?", sourceObjective = "Sammelt Proben von Tieren in der Biokuppel: Primus.", progress = "Habt Ihr alle?", completion = "Hmm, die sehen tatsächlich gesund aus.\n\nDas ist etwas unerwartet, aber gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[86603] = { id = 86603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roch-Quetball", description = "Anscheinend war einer der Nekrorochen, die Ihr mitgebracht habt, trächtig. Ich habe mich also den ganzen Tag um ein Neugeborenes kümmern müssen. Danke dafür.\n\nWürde es Euch etwas ausmachen, seine Reflexe für mich zu testen?", sourceObjective = "Fangt einen Ball 10-mal, während Ihr mit Eurem Nekrorochenjungen spielt.", progress = "Seid Ihr fertig mit Spielen... ähm, ich meine... seid Ihr fertig damit, die Reflexe des Welpen zu testen?", completion = "Diese Daten sollten hilfreich sein, habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[86604] = { id = 86604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragwürdige Motive", description = "Der Schlamm, den Hemet Euch hat einsammeln lassen, könnte uns nützlich sein. \n\nGeht und sammelt den Schlamm direkt von den Nekrorochen. Ihr könnt diesen Betäubungspfeil nutzen, um sie in Reichweite zum Einsammeln zu bringen.", sourceObjective = "Sammelt 7 Nekrorochenschleim.", progress = "Habt Ihr den Schlamm gesammelt?", completion = "Das sollte für verschiedene Projekte in der Oase von Nutzen sein. Ihr habt unseren Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[86605] = { id = 86605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vitaminkur", description = "Nach gründlicher Untersuchung der von Euch gelieferten Proben zeigt sich, dass die Nekrorochen unter Vitaminmangel leiden.\n\nVe'nari wandte sich an Marileth, der daraufhin etwas anmischte und es auf ihre Bitte hin nochmals zubereitete, nachdem er die Seuche entfernt hatte.\n\nBitte sammelt die Nekrorochen ein, damit wir die ersten Chargen testen können.", sourceObjective = "Fangt 6 ruhige Nekrorochen ein und bringt sie zum Anbindepfosten bei Om'talad.", progress = "Habt Ihr die Nekrorochen gesammelt?", completion = "Hervorragende Arbeit! Wir werden die Mixtur verabreichen und die Wirkung überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86606] = { id = 86606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glibber aus Gold", description = "Unsere Verwalter haben noch nicht die tägliche Beseitigung der Nekrorochen-Absonderungen vorgenommen. In Tazavesh stehen zahlreiche Interessenten für dieses Material Schlange. Sie brauchen es dringend. Deshalb fällt es Euch zu, es zu sammeln.\n\nNehmt das Sauggerät. Ihr werdet dafür entlohnt.", sourceObjective = "Beseitigt 25 geronnene Klumpen in der Oase.", completion = "Die Oase wird sehr von Euren Bemühungen profitieren. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[86607] = { id = 86607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Rochenrennen", description = "Diese Nekrorochen sind sehr gut auf die Behandlung angesprungen, die Ihr ihnen verabreicht habt! Sogar so gut, dass einer von ihnen etwas Energie abbauen muss.\n\nKönnt Ihr ihn außer Puste bringen?", sourceObjective = "Fordert den rasenden Nekrorochen zu einem Wettrennen heraus und erreicht die Ziellinie.", progress = "Habt Ihr ihn schon aus der Puste gebracht?", completion = "Das ging schnell, {name}! Schneller als ich es dieser Tage schaffen würde. Ich überlasse Euch alles, was Eile hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[86610] = { id = 86610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Leere noch Nacht" }
quests[86618] = { id = 86618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Führerschein benötigt", description = "Also gut. Bevor Ihr da raus geht und jemanden überfahrt, sollten wir sicherstellen, dass Ihr auch wisst, wie man das richtig tut.\n\nWir machen Euch mit dem Fahrzeug, dem F.A.H.R.E.N.-Dienst, den wir anbieten, vertraut und damit, wie man stilvoll darin herumfährt.", sourceObjective = "Lernt, wie man den 99-G-Genickbrecher fährt.", progress = "Tretet einfach aufs Gaspedal, der Rest erschließt sich Euch ganz natürlich.", completion = "Gute Arbeit da draußen! Diese Fahrzeuge sind allerdings nicht versichert, wenn Ihr also auf irgendwelche Probleme stoßt, müsst Ihr selbst damit zurechtkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86619] = { id = 86619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theatertruppe" }
quests[86696] = { id = 86696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederholte Schattenstörung" }
quests[86697] = { id = 86697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Räumtrupp", description = "Auch wenn wir da draußen Bots und keine Arbeiter haben, gibt es nach wie vor Monster, mit denen sie sich in die Haare, äh, in die Verkabelung kriegen.\n\nGeht da raus und merzt die Wildtiere aus. Das sollte unsere Bots davor bewahren, beschädigt zu werden, und verhindern, dass die Garantie erlischt.\n\nJe länger sie da draußen bleiben können, desto länger können wir hier bleiben!", sourceObjective = "Tötet Gegner auf den Zuckenden Feldern in den Schallenden Tiefen.", completion = "Genau das meine ich!\n\nJetzt können die Bots arbeiten, ohne von all diesen miesen Schwarzblutmonstern gestört zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[86698] = { id = 86698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[86699] = { id = 86699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewegt Euch", description = "Der große Stylecheck bietet uns die Gelegenheit, gut dazustehen, {class}.\n\nDie Kamera sorgt dafür, dass wir immer gut aussehen.\n\nAlso konzentriert Euch auf mich und meine Kamera, folgt meinen Anweisungen und ich rücke Euch ins beste Licht!", sourceObjective = "Konzentriert Euch auf den Fotografen und folgt den Anweisungen.", progress = "Konzentriert Euch auf mich und folgt meinen Anweisungen. \n\nIch rücke Euch ins beste Licht.", completion = "Die Kamera lügt nicht, {name}.\n\nIhr seid ein schicker {class}.", sourceObjectiveStatus = "unverified-source-field" }
