quests[86706] = { id = 86706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Wissen der Vergangenheit", description = "Grüße, {race}. Ich muss Euch um Hilfe bitten. Soridormi und unser Blut sind nach Khaz Algar gereist, um den Kampf gegen den neuen Meister der Leere zu unterstützen.\n\nWir glauben, dass wir wertvolle Einblicke und Informationen über vergangene Angriffe durch die Leere bieten können.\n\nSucht sie am südlichen Ende des Kernwegs auf.", sourceObjective = "Sucht Soridormi in der Nähe des Kernwegs in Dornogal auf der Insel von Dorn auf.", completion = "Ihr kommt genau rechtzeitig, wie immer! Sprechen wir über das, was mich herführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86707] = { id = 86707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auferstehung der Schattenwache" }
quests[86709] = { id = 86709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana fällt vom Himmel" }
quests[86728] = { id = 86728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Schleuse: Müllentsorgung", description = "Hey, Kumpel. Ich habe Gerüchte gehört, dass so ein Schwachkopf bei den Wasserwerken in den Schallenden Tiefen Energie abzapft.\n\nUnsere Steinfreunde zu bestehlen ist nicht gut fürs Geschäft. Wir können nicht dulden, dass das so weitergeht.\n\nEuer Ruf als effizienter Müllentsorger eilt Euch voraus und manche Geschäftsleute sind wirklich der letzte Abschaum.\n\nWürdet Ihr mir einen Gefallen tun? Waffen sind optional, hier ist die richtige Einstellung gefragt... wenn Ihr versteht, was ich meine.", sourceObjective = "Besiegt Giesel Gigaschock in Operation: Schleuse.", progress = "Hey, habt Ihr den \"Abschaum\" beseitigt?", completion = "Danke, Kumpel. Die Kartelle werden nicht vergessen, was Ihr für sie geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[86731] = { id = 86731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ursprünglicher Pfad durch die Zeit", description = "Seit Eure Stadt vom Himmel gefallen ist, habe ich mehr über die Geschichte dieser Welt und die Herausforderungen gelernt, denen sich Helden wie Ihr gestellt haben.\n\nWenn wir aus der Vergangenheit lernen, können wir unsere Zukunft sichern. Reist durch die Zeit zum bescheidenen Anfang, um diese Bedrohungen noch einmal zu besiegen und diese Lektionen weiterzugeben.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Welche Lektionen bringt Ihr von Euren Reisen durch die Zeit mit?", sourceObjectiveStatus = "unverified-source-field" }
quests[86775] = { id = 86775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiße Preise", description = "Manchmal kommen mehr Aufträge rein, als wir bearbeiten können. Ihr wisst, was das bedeutet! Ordentlich Knete. Helft bei dynamischen Preisgestaltungen aus und wir sorgen dafür, dass man Euch für Eure Hilfe dankt.", sourceObjective = "Schließt eine dynamische Preisgestaltung mindestens einmal ab.", progress = "Haltet die Ohren offen für den Fall, dass wir Hilfe brauchen. Das passiert für gewöhnlich innerhalb einer Stunde.", completion = "Wow. Wir waren echt überfordert. Danke für die Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[86782] = { id = 86782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atrium-Ambulanz", description = "Die Nekrorochen wurden im Atrium untergebracht, wo Hemet sich um sie kümmert.\n\nEr hat um Eure Anwesenheit gebeten.", sourceObjective = "Trefft Euch mit Hemet Nesingwary im Atrium.", completion = "Schön, dass Ihr kommen konntet.\n\nSollen wir loslegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[86783] = { id = 86783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnige Rochentage", description = "Gut. Bringen wir diese Rochen in die Biokuppel: Primus im Norden!", sourceObjective = "Trefft Euch mit Hemet Nesingwary in der Biokuppel: Primus.", completion = "Bereit für eine zweite Runde?", sourceObjectiveStatus = "unverified-source-field" }
quests[86786] = { id = 86786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leerenjäger", description = "Die Leere verkündet alle Wahrheiten, {name}. Und in keiner davon besiege ich Ramon'ta ohne etwas Hilfe.\n\nUnd hier kommt Ihr ins Spiel.\n\nMein Ziel ist ein kosmischer Wurm, der als Ramon'ta der Unersättliche bekannt ist. Er hat recht klein angefangen, doch mit jedem Leerenwesen, das er verschlingt, wächst er. Und seine Macht.\n\nWenn wir ihn besiegen, kann ich seine Macht für mich beanspruchen. Werdet Ihr mir helfen?", sourceObjective = "Helft Leona den ermächtigten kosmischen Wurm zu besiegen und seine Macht einzufordern.", completion = "Ihr wart soweit hilfreich. Im Gegenzug werde ich Euch erlauben, in die Geschichte dieses verworfenen, kaputten Planeten einzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86800] = { id = 86800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt sie fort" }
quests[86801] = { id = 86801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Mannigfaltigkeiten", description = "Die Welt wird in unserer Mannigfaltigkeit ertrinken und den Hunger unserer Götter stillen. Nur wer im Blut unserer Feinde badet, kann sich zum Wohlwollen unserer Meister erheben und ihre grenzenlose Mannigfaltigkeit für sich selbst entfesseln.", sourceObjective = "Bringt die Gesichtslosenmaske der Mannigfaltigkeiten in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Mannigfaltigkeiten auf den Altar.", completion = "Gesättigt vom Blut der Mannigfaltigkeiten, jetzt und auf ewig. Denn unsere Zahlen sind endlos und werden die Welt verschlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86820] = { id = 86820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaschmiede Omega: Dimensius naht", sourceObjective = "Besiegt Dimensius im Schlachtzug Manaschmiede Omega.", sourceObjectiveStatus = "unverified-source-field" }
quests[86821] = { id = 86821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Losgelöst und unwohl" }
quests[86835] = { id = 86835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren!", description = "Wir haben den Großteil der Stadt stabilisiert und so viele wie möglich gerettet, aber unsere Arbeit ist noch nicht getan.\n\nDer Raumgänger muss noch da draußen sein und nach dem gegnerischen Kommandanten suchen. Wir haben den Großteil der Stadt bereits abgesucht, daher muss er irgendwo sein, wo wir noch nicht nachgesehen haben.\n\nKommt, {name}. Trefft mich bei Myzas Oase.", sourceObjective = "Macht den Raumgänger in Tazavesh ausfindig.", completion = "Ich habe unsere Beute gefunden, aber leider nicht, bevor sie in diesen Unterschlupf einbrechen konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[86853] = { id = 86853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Krieges: Lorenhall", description = "Untersucht Lorenhall! Berichten zufolge gibt es im Gebiet einen wachsenden Konflikt. Geht da raus und schaut Euch die Sache an.", sourceObjective = "Sammelt bei aktivem Kriegsmodus 100 Funken des Krieges in Lorenhall.", progress = "Geht und schließt Eure Untersuchung ab.", completion = "IHR HABT ÜBERLEBT? Und obendrauf mit unversehrten Gliedmaßen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[86869] = { id = 86869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Saboteure von Shan'dorah" }
quests[86872] = { id = 86872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasentauchen: Experimentelle Auslöschung" }
quests[86905] = { id = 86905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder Krankentage", description = "Als wir begonnen haben, uns um diesen Wald zu kümmern, haben wir durchaus mit Problemen mit den Tieren hier gerechnet, aber wir hätten nie erwartet, dass uns kranke Tiere angreifen würden! Ständig wird jemand aus meinem Team krank und muss sich frei nehmen. Das wirkt sich natürlich negativ auf unseren Profit aus. Könntet Ihr vielleicht ein paar Tiere für uns loswerden, damit wir wieder an die Arbeit gehen können?\n\nWenn Ihr den Auftrag erledigt habt, kümmert sich meine Assistentin um die Bezahlung.", sourceObjective = "Beseitigt 8 kranke Kreaturen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86915] = { id = 86915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partei für ein Kartell ergreifen" }
