quests[86924] = { id = 86924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenigstens ein paar fangen" }
quests[86934] = { id = 86934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müll zu Gold", description = "Ey! Ich hab gehört, dass Ihr einiges von dem Müll in Lorenhall beseitigt habt. Gut für Euch.\n\nHättet Ihr Interesse daran, das etwas buchstäblicher zu tun?\n\nIst schmutzige Arbeit, aber da lässt sich ordentlich Gold machen, wenn man sich nicht ganz blöd anstellt. Wenn Euch das anspricht, dann meldet Euch bei Chef Carlo bei der Lorenhaller Stadtsanierung.\n\nUnd sagt ihm, dass ich Euch schicke, dann bekomme ich meinen Rekrutierungsbonus!", sourceObjective = "Sprecht mit Carlo Schmierknarr bei der Lorenhaller Stadtsanierung.", completion = "Renzi hat in letzter Zeit ordentlich Rekruten rangeschafft. Ihr werdet einiges an Konkurrenz haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[86935] = { id = 86935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praktische Ausbildung", description = "Wenn Ihr nach Arbeit sucht, S.C.H.R.O.T.T. heuert immer an. Das steht für \"Spezielle Checks, Hygienemaßnahmen, Reparaturen, Observationen, Tests und Theorien\".\n\nWir streifen durch Lorenhall, schaufeln Müll und sieben die guten Teile aus. Wertvolles wird hierhergebracht, gereinigt und an alle verkauft, die es haben wollen.\n\nFindet etwas Nützliches und Angelo hier wird es Euch abkaufen. Seht Euch an, was er auf Lager hat, dann sucht mich draußen auf. Ich zeige Euch, wie der Hase läuft.\n\nAber letztendlich ist es Müllschaufeln, keine Raketenwissenschaft.", sourceObjective = "Schaut Euch Angelo Rostlaubes Waren in der Lorenhaller Stadtsanierung an und schließt danach einen S.C.H.R.O.T.T.-Auftrag in Lorenhall ab.", progress = "Ihr solltet vielleicht in Augenschutz investieren. Oder zumindest in ein paar wirklich dicke Handschuhe. Und Nasenstöpsel.", completion = "Ah, ich liebe den Geruch von Profit zu unklarer Stunde.\n\nWenn Ihr noch mehr Knete machen wollt, dann findet mich draußen. Wir werden zusammen wirklich gute Arbeit leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[86936] = { id = 86936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückisches Holz", description = "Unsere Leute haben gerade Bäume in diesem Bereich gefällt, um Platz für neue Häuser zu schaffen, als sie sich plötzlich entwurzelt und damit begonnen haben, alles kurz und klein zu schlagen. Als wären all die kranken Tiere nicht schon schlimm genug, scheinen jetzt auch noch diese Bäume entschlossen zu sein, uns von unserer Arbeit abzuhalten.\n\nWenn Ihr ein paar ausmerzen könntet, würde das unser Bauvorhaben wirklich beschleunigen.", sourceObjective = "Tötet 3 verfaulende Treants.", sourceObjectiveStatus = "unverified-source-field" }
quests[86943] = { id = 86943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losbohren", sourceObjective = "Besiegt die Präzisionsbohrmaschine in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[86946] = { id = 86946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgewickelt und aufgelöst", description = "Euch beide auf dem Schlachtfeld zu sehen, war fabelhaft. Es ist wirklich eine Freude, Euch bei der Arbeit zuzusehen. Hätten Eure sogenannten Freunde Euch doch nur von Anfang an die Wahrheit anvertraut. Der Raumgänger mag Euch mit seinen Taten in der Gegenwart nicht getäuscht haben, doch über seine Taten in der Vergangenheit, die uns an diesen Punkt gebracht haben... bleibt er recht schweigsam.\n\nIch kann Euch und Alleria nicht guten Gewissens weiter die Wahrheit verwehren.", sourceObjective = "Findet Alleria, bevor sie den Raumgänger konfrontiert.", completion = "Wie man es von der Vorbotin erwartet. Sie erfüllt ihre Schwüre bis ins kleinste Detail, doch hinterlässt ihre Verbündeten am Boden zerstört. Gäbe es nur eine andere Möglichkeit, den alles Verschlingenden daran zu hindern, sich wieder zu erheben...\n\nMit meinem Reshiiband kommt Ihr Dimensius einen Schritt näher. Doch Ihr braucht mindestens doppelt so viele Streitkräfte, um seine schreckliche Aura zu überwinden. Viel Glück, {name}. Behaltet die Vorbotin genau im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[86947] = { id = 86947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winzig, teuer und tödlich", sourceObjective = "Besiegt Baxx den Beschaffer in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[86949] = { id = 86949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue Besatzungsmitglieder", sourceObjective = "Besiegt Prezly Wogenspalter in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[86952] = { id = 86952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nähert Euch der Schabe", sourceObjective = "Besiegt Chahbe in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[86960] = { id = 86960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zu guter Gesundheit", description = "Ich bin eigentlich die Gesundheitsberaterin, aber jetzt bin ich diejenige, die krank geworden ist! Ich habe Medizin in dieser Truhe, aber ich habe den Schlüssel verloren und ich befürchte, ein Tier hat ihn nach dem Angriff gefressen. Schaut doch bitte, ob Ihr ihn findet.", sourceObjective = "Findet einen Schlüssel, um die Truhe zu öffnen und die Medizin zu holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86961] = { id = 86961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baulöwe", description = "<Der Brief ist an \"<Der/Die:c> {class}, <der/die:c> Gallywix erledigt hat\" adressiert. Ihr braucht frustrierend viel Zeit, die vielen Lagen an Paketband aufzureißen, mit dem der Umschlag zugeklebt wurde.>\n\nHey <Kollege/Kollegin>,\n\nIhr habt Euch echt einen Namen gemacht. Habt scheinbar keine Angst, die Ärmel hochzukrempeln und richtig anzupacken. Es gibt Leute, die das wirklich zu schätzen wissen.\n\nLasst uns mal quatschen. Trefft mich in meiner Lagerhalle. Vielleicht können wir Geschäftspartner werden.", sourceObjective = "Findet Euren potenziellen \"Geschäftspartner\" und sprecht mit ihm.", completion = "Ich freue mich bereits, Geschäfte mit Euch zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[86962] = { id = 86962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut in der Wunde", sourceObjective = "Bringt die Medizin zurück.", sourceObjectiveStatus = "unverified-source-field" }
