quests[87000] = { id = 87000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Holz wird zurückgelassen", description = "Als wir von der örtlichen Fauna angegriffen wurden, mussten wir den Großteil des Holzes zurücklassen, das wir bereits gesammelt hatten. Während wir darauf warten, dass Ihr unser kleines Tierproblem löst, könnten wir die Zeit nutzen, um Bretter aus dem Holz zu fertigen und unser Bauprojekt voranzutreiben. Ich freue mich über jedes einzelne Scheit.", sourceObjective = "Sammelt 8 Holzscheite.", sourceObjectiveStatus = "unverified-source-field" }
quests[87001] = { id = 87001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Splitterimpuls", description = "Die schreckliche Kreatur Splitterimpuls befindet sich verborgen in einer Stasiszelle am Schattenpunkt. Sie wird nicht als Gefangener gehalten, sondern als Waffe, die entfesselt werden soll, wenn wir es am wenigsten erwarten.\n\nFertigt einen Schlüssel, um die Stasiszelle von Splitterimpuls zu öffnen und diese Bedrohung für alle zu offenbaren.", sourceObjective = "Sammelt einen Berechnungsbehälter, eine Markierungsmatrix und etwas leerenfusioniertes Harz, um einen Schlüssel zu fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87008] = { id = 87008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spontaner Hochzeitsplaner", description = "Heeey, wenn das nicht mal eine denkwürdige Hochzeit war!\n\nIhr wart ganz okay. Es lief alles glatt, und das einzige Problem ist das, was meine Kleine jetzt an der Backe hat. Von daher ist alles gut zwischen uns.\n\nIch weiß, dass Braut und Bräutigam Euch ihren Dank ausrichten wollen, also sprecht doch mal mit ihnen.", sourceObjective = "Sprecht mit Neenee und Vrizek.", progress = "Ist es nicht einfach schön, diese beiden Verrückten zusammen zu sehen?", completion = "Ihr seid meiner kleinen Prinzessin gerecht geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[87010] = { id = 87010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berechnungsbehälter", description = "Ein Berechnungsbehälter lässt sich nicht gerade einfach herstellen.\n\nIch habe schon länger keinen mehr gefertigt, da Diebe die Datenstäbe gestohlen haben, die ich dafür benötige. Wenn Ihr die Stäbe zurückbringen könnte, kann ich einen Behälter herstellen.\n\nDoch seid gewarnt! \n\nDie Stäbe sind recht schwer und werden nicht leicht zu tragen sein. Ich bin bekannt dafür, sie gerne mal fallen zu lassen.", sourceObjective = "5 schwere Stäbe der Variablen zu Ingenieur Om'loof gebracht", progress = "Konntet Ihr finden, was wir brauchen?", completion = "Diese schweren Stäbe sind recht unangenehm zu tragen. Ich bin froh, dass die Aufgabe, sie zu transportieren, in Eure Hände gefallen ist.\n\nDoch Eure Mühen waren es wert! Ich habe gefertigt, was Ihr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[87284] = { id = 87284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein strahlendes Echo", description = "<In Eurer Hand haltet Ihr eine kleine Azeritkugel. Ihr Licht ist gleichmäßig und hell, doch der Klang, den sie aussendet, ist klagend und sehnsüchtig. Sie zieht ganz leicht an Euch.>", sourceObjective = "Bringt das strahlende Echo zu einer Weltenseelenerinnerung und lasst es dann frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[87285] = { id = 87285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markierungsmatrix", description = "Eine Markierungsmatrix muss auf die Leerenenergien der Schattenwache eingestimmt werden. Es liegt an Euch, Proben dieser Energie zu beschaffen.\n\nMeine Eindämmungsfalle ist darauf ausgelegt, Anhänger der Schattenwache festzusetzen, um Euch zu ermöglichen, die Leerenmarkierungen zu extrahieren, die an ihre verdorbenen Energien gebunden sind.\n\nMit diesen Markierungen kann ich eine Matrix erstellen, mit der Ihr Euer Werkstück einstimmen könnt, um an leerenbetriebenen Konstrukten zu arbeiten.", sourceObjective = "Extrahiert 8 Leerenmarkierungen von Schattenwachengegnern.", progress = "Habt Ihr die Aufgabe verrichtet?", completion = "Erzählt mir bloß nicht, was Ihr mit dieser Matrix herstellen wollt. Ich hoffe, es wird eine spannende Kreation!", sourceObjectiveStatus = "unverified-source-field" }
quests[87289] = { id = 87289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Wenn Ihr nach Bier sucht, davon haben wir mehr als genug! Oder zumindest hätten wir das, wenn diese Dracthyr sich endlich beeilen würden, den Rest der Fässer herzubringen.\n\nEinige der Dracthyr sind hergekommen, um mit uns zu feiern und haben sich entschlossen, beim Transport des Biers zu helfen. Fässer rollen? So geht man doch nicht mit einem guten Gebräu um!\n\nWürdet Ihr mir zur Hand gehen und diese Fässer nach Kharanos bringen? Versucht nur, sie nicht kaputt zu machen!", sourceObjective = "Liefert die Fässer in Kharanos ab.", progress = "Vorsichtig mit den Fässern! Gutes Bier sollte man nicht so durchschütteln.", completion = "Ich bin froh, diese Lieferung wohlbehalten zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[87290] = { id = 87290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oase", description = "Grüße Euch, {name}. \n\nVe'nari bat mich, Euch zu finden. Sie sagte, Ihr sollt sie in der Oase treffen.\n\nIch werde bald zu Euch stoßen. Ich muss hier erst noch einige Besorgungen erledigen.", sourceObjective = "Reist zur Oase von K'aresh.", completion = "Ve'nari hat mir nicht gesagt, dass sie Außerweltler anstellt. Gute Hilfe ist schwer beizukommen. Ich schätze, Ihr werdet genügen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87291] = { id = 87291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salatbar", description = "Hemet, Om'talad und ich haben unsere Köpfe zusammengesteckt, um zu sehen, was wir für die Schoßkäfer tun können. Offenbar hat ihre ursprüngliche Nahrungsquelle den Zusammenbruch von K'aresh nicht überstanden!\n\nGlaubt Ihr, Ihr könntet einige Stachelblüten und glänzende Kastanien sammeln, und daraus einen bunten Teller für sie zusammenstellen?", sourceObjective = "Sammelt 7 zerhackte Oasenpflanzen und platziert 3 Pflanzenteller.", progress = "Habt Ihr die Schoßkäfer gefüttert?", completion = "Das hat prima geklappt! Ihr habt wirklich ein Händchen dafür, ansprechende Charcuterie-Arrangements zu erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87292] = { id = 87292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstrickt im Grünen", description = "Unsere Bienen haben Wunder in der Kultivierung der lokalen Flora bewirkt. Einige der Pflanzen weisen nahezu explosives Wachstum auf.\n\nAllerdings haben sich die Schoßkäfer in ihren Wurzeln verfangen. Ich habe sie den ganzen Morgen lang entwirrt. Könnt Ihr helfen?", sourceObjective = "Befreit 10 feststeckende Schoßkäfer.", progress = "Habt Ihr die Schoßkäfer entwirrt?", completion = "Endlich! Hoffen wir, dass diese kleinen Schoßkäfer sich keinen neuen Ärger einhandeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[87293] = { id = 87293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schamlose Werbung", description = "Schoßkäfer waren hier auf K'aresh einst äußerst begehrte Haustiere. \n\nIch glaube, dass wir sie nutzen können, um interessierte Parteien in Tazavesh für uns zu gewinnen, damit die Oase mehr Unterstützung und Spenden bekommt.\n\nIch würde diese Theorie gern ausprobieren.", sourceObjective = "Sammelt in Tazavesh Unterstützung für die Oase.", completion = "Die Schoßkäfer scheinen heute genauso beliebt zu sein wie damals. Hervorragend.", sourceObjectiveStatus = "unverified-source-field" }
quests[87294] = { id = 87294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kosmische Gewissheit", description = "Ich hab eine Idee, {name}. Alle scheinen die Schoßkäfer zu lieben, also habe ich sie vergrößert, ihnen Hüte aufgesetzt und sie an malerischen Orten platziert. Nehmt diese Kamera und macht ein paar Fotos mit den Schoßkäfern.\n\nWenn ich richtig liege, wird uns das noch mehr Unterstützung für unsere Bemühungen sichern.", sourceObjective = "Macht ein S.E.L.F.I.E. mit verschiedenen Schoßkäfern, die Hüte tragen.", progress = "Habt Ihr die Fotos gemacht? Vergesst nicht, auch Euer eigenes reizendes Antlitz darauf einzufangen.", completion = "Sie sind hervorragend. Eure fotografischen Fähigkeiten verdienen großes Lob. Mir gefällt besonders das hier mit Graf von Goldig.\n\nVielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[87297] = { id = 87297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheck einlösen", description = "Es gibt noch eine Sache, die wir begradigen müssen.\n\nKommt schon. Grimla wartet auf uns in der Hotellobby.", sourceObjective = "Sprecht mit Grimla Knisterkurbel im Hotel Inkontinental.", progress = "Tag auch, Chef.", completion = "Wir haben allen gezeigt, dass Lorenhall vor niemandem in die Knie geht. Wenn sie uns zwingen wollen, dann sollten sie sich lieber auf einen höllischen Kampf gefasst machen.\n\nDie Zukunft wird nicht perfekt sein... aber solange wir es selbst in der Hand haben, sie zu ruinieren, soll mir das recht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[87298] = { id = 87298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenfusioniertes Harz", description = "Leerenfusioniertes Harz gehört nicht zu meinen gewöhnlichen Werkstücken, doch es gibt einen Weg, wie ich es für Euch herstellen kann.\n\nLeerenenergie sickert weiter durch die Risse unserer Schilde und kontaminiert die Pflanzen in den Kuppeln. Wenn wir die kontaminierten Pflanzen vernichten, könnten sie uns die Zutaten liefern, die wir zur Herstellung des Harzes benötigen.\n\nZerstört leerenbesudelte Wachstume und bringt mir alle Leerenkörnchen, die Ihr finden könnt.", sourceObjective = "Sammelt 35 Leerenkörnchen.", progress = "Schnell, Ihr müsst diese Aufgabe abschließen!", completion = "Ich fürchte, die Kontaminierung wird bald wieder Einzug halten, doch wir sollten ihren Fortschritt damit einige Tage verlangsamt haben!\n\nOh, seht mal, was ich dank Euren Bemühungen geschaffen habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[87299] = { id = 87299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie alt sind diese Dinger?", description = "Marran wollte sich selbst zur neuen Herrscherin Stromgardes erklären. Während einige in der Armee ihren Aufstand unterstützen, gibt es noch viele von uns, die Lord Danath Trollbann die Treue halten.\n\nDoch als wir uns lossagten, war Marran bereit. Sie führt ein Heer aus Soldaten, wie ich es noch nie zuvor gesehen habe. Sie nennen sich die \"Rote Dämmerung\", doch ich glaube, sie sind nichts weiter als Banditen, die Uniformen tragen, die sie aus unseren Vorräten entwendet haben!\n\nHelft uns, ihre Schläger auszuschalten, und sammelt jegliche Beweise, die zeigen, wer sie in Wahrheit sind!", sourceObjective = "Sammelt 20 Beweisartikel von den Truppen der Roten Dämmerung in Stromgarde.", progress = "Einiges von diesem Zeug muss mindestens zwanzig Jahre alt sein...", completion = "Ich wusste es! Ihre Armee besteht aus Mitgliedern der Defias, des Scharlachroten Kreuzzugs und des Syndikats. Mit anderen Worten: Banditen, Fanatiker und Verräter!\n\nDieser Beweis sollte anderen helfen zu erkennen, dass man Marran nicht trauen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[87301] = { id = 87301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebundene Batterie", description = "Ungebundene Batterien sind schwer herzustellen, da sie flüchtige Energien benötigen, die aus Leerenlagerzellen in den ungebundenen Raum sickern.\n\nIch kenne jedoch jemanden, der diese Energie sammeln kann. Wenn Ihr die Energie extrahieren, speichern und wieder zu mir bringen könnt, dann haben wir die nötigen Komponenten, um eine Batterie herzustellen.\n\nSprecht mit Myi Koo und sammelt Energie, dann können wir eine Batterie herstellen.", sourceObjective = "Trefft Euch mit Myi Koo, betretet den ungebundenen Raum und sammelt 10 ungebundene Energieproben.", completion = "Myi Koo ist voll geladen mit ungebundener Energie. Mehr als genug, um eine Batterie zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87302] = { id = 87302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Rivalen" }
quests[87303] = { id = 87303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seitenstraßen räumen" }
quests[87304] = { id = 87304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zu räumen" }
quests[87305] = { id = 87305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "F.A.H.R.E.N.-Gefahr" }
quests[87306] = { id = 87306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaja'cruisen" }
quests[87307] = { id = 87307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müllentsorgung" }
quests[87321] = { id = 87321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerledigte Dinge", description = "Hey, ich kann Euch nicht genug dafür danken, was Ihr für mich... und für ganz Lorenhall getan habt.\n\n<Marin schaut zu Sprinkel, bevor er wieder zu Euch blickt.>\n\nIch weiß, dass Ihr alle Hände voll zu tun hattet, seitdem Renzik und Gazlowe Euch hergebracht haben. Und Ihr habt alles getan, worum wir Euch gebeten haben. Doch es gibt noch eine Sache, die erledigt werden muss.\n\nTrefft Euch mit Gazlowe im Hotel. Ich bin mir sicher, dass er sich dort über Eure Hilfe freuen würde.", sourceObjective = "Trefft Euch mit Monte Gazlowe im Hotel Inkontinental in Lorenhall.", completion = "Danke fürs Kommen.\n\nEs gibt noch eine Sache, die wir tun müssen, um die Dinge in Lorenhall zu begradigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87324] = { id = 87324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haufen aus Leerenfluchedelsteinen", description = "Leerenfluchedelsteine sind gefährlich! \n\nDie Schattenwache versteckt die Edelsteine im ungebundenen Raum. Ihr müsst da rein und sie finden. Doch seid gewarnt: Nicht nur Ihr werdet dort nach den Edelsteinen suchen!\n\nIch habe die Positionen der Verstecke markiert, doch es liegen dort auch andere Edelsteine verstreut. Schnappt Euch, was Ihr finden könnt, dann habt Ihr am Ende einen netten Haufen Edelsteine.", sourceObjective = "Sammelt 20 Leerenfluchedelsteine.", progress = "Schnell, schnappt Euch diese Edelsteine, bevor es jemand anderes tut.", completion = "Ich wusste, dass Ihr das schaffen würdet. Nach Abzug meines Finderlohns solltet Ihr immer noch einen netten Haufen Edelsteine haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[87327] = { id = 87327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Widerstandsfähigkeit eines Herausforderers", description = "Wow {name}, Ihr habt ein paar unglaublich gruselige Dungeons ausgeräumt UND auch noch überlebt!\n\nKommt zu mir. Möglicherweise kann ich Eure anspruchsvollsten Schlüsselsteine widerstandsfähiger machen.", sourceObjective = "Trefft Euch mit Lindormi, um mehr über widerstandsfähige Schlüsselsteine zu erfahren.", completion = "Da Xal'ataths plötzliche und unvermeidbare Treuebrüche keine Probleme für Euch zu sein scheinen, stelle ich sicher, Euch ab sofort ausschließlich richtig widerstandsfähige Schlüsselsteine zu geben.\n\nEs ist aber auch in Ordnung, mich um einfachere Schlüsselsteine zu bitten. Jeder kann mal eine Pause brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87328] = { id = 87328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wahrhaft verstörender Anblick", description = "{name}, wir haben viel zu besprechen. Die neue Bedrohung durch die Leere bringt uns alle in Gefahr. Doch für uns ist das nicht das erste Mal. Es gibt Hinweise in unseren früheren Begegnungen.\n\nEiner davon liegt im Fall des Schwarzbluts. In der Vergangenheit nutzte N'Zoth es, um Visionen zu erzeugen.\n\nVielleicht können wir herausfinden, wie man dessen Effekt bekämpft, wenn wir zu diesen Momenten zurückkehren.\n\nKommt, helft mir, das Portal zu öffnen.", sourceObjective = "Sprecht mit Soridormi, um ihr beim Öffnen des Portals zu helfen.", progress = "Seid Ihr bereit, zu diesen verstörenden Visionen zurückzukehren?", completion = "Ausgezeichnet! Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[87329] = { id = 87329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die finstersten Erinnerungen", description = "Seid Ihr bereit?\n\nDer Pfad durch die Zeitwege ist dorthin geöffnet, wo wir die Visionen zuletzt betreten haben.\n\nRechnet damit, dass Euer Verstand auf die Probe gestellt wird. Bei diesem ersten Versuch haltet Ihr vielleicht nicht sehr lange durch.\n\nDas Portal steht für Euch bereit, {name}. Gute Reise.", sourceObjective = "Interagiert mit dem Portal zu den verstörenden Visionen, um die Schrecken des Schwarzbluts wiederzuentdecken.", progress = "Wir müssen auf unserem früheren Wissen aufbauen. Habt Ihr etwas Neues herausgefunden?", completion = "Alles ist gut, {name}. Ihr seid zurück. Ihr habt gute Arbeit geleistet. Denkt daran, das war nur eine Erinnerung an eine Vision.\n\nWir werden Euch vor der Vergangenheit schützen, doch die Bedrohung der Leere für uns alle ist in der Gegenwart so real wie zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[87332] = { id = 87332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sammlung an Variablen", description = "Mein Assistent Augermu hat Euch und die Zeitwege überwacht, während Ihr in der Vergangenheit wart. Er hat eine Möglichkeit gefunden, wie Ihr einige der Gaben replizieren könnt, die Abenteurer bei ihrer ersten Begegnung mit diesen Visionen nutzten.\n\nGebt ihm einige der versetzten verderbten Andenken, die Ihr bei Eurer Erfahrung erblickt habt, zur weiteren Analyse.", sourceObjective = "Sprecht mit Augermu und fragt ihn, was Ihr mit den versetzten verderbten Andenken machen könnt.", completion = "Hallo, {class}. Ihr seid also mein neuestes Testobjekt - ich meine, Ihr wollt die Visionen der Vergangenheit besuchen?\n\nIch habe gehört, dass Ihr einige versetzte verderbte Andenken von Eurem letzten Ausflug mitgebracht habt.\n\nPerfekt! Ich zeige Euch, was Ihr damit machen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87335] = { id = 87335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerhallende Lektionen", description = "Wir können Eure versetzten verderbten Andenken nutzen, um Echos von N'Zoth zu erschaffen.\n\nIch will Euch nicht mit den Einzelheiten langweilen, außer Ihr wollt sie gerne hören.\n\nNein? Na gut. \n\n<Augermu wirkt leicht enttäuscht.>\n\nJe mehr Echos Ihr habt, umso näher können wir einer Version Eurer Selbst kommen, die besser auf die Visionen vorbereitet ist.\n\nFangen wir an.", sourceObjective = "Arbeitet mit Augermu zusammen, um ein Echo von N'Zoth zu erschaffen und es in das Stundenglas der verstörenden Visionen zu geben.", progress = "Konntet Ihr das erste Echo von N'Zoth einsetzen?", completion = "Je mehr Echos Ihr erschafft, umso mehr Andenken wird es Euch kosten.\n\nWenn Ihr wissen wollt, wie viele Ihr für das nächste braucht, fragt mich nur. Ich finde es raus. \n\nDiese Visionen sind so unheimlich - aber gemeinsam werden wir Erfolg haben, {class}. Die Leere hat keine Chance gegen uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[87336] = { id = 87336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an Erinnerungen", description = "Nun, da wir das Stundenglas auf Euch eingestellt haben, könnt Ihr die verstörenden Visionen betreten, wann immer Ihr wollt. Ihr braucht keine Schlüssel mehr, wenn Ihr in der Zeit zurückreist!\n\nEs gibt allerdings eine Einschränkung. Das Stundenglas ist zerbrechlich und ich muss es jede Woche härten, damit es weiteren Echos von N'Zoth widerstehen kann. Wer hätte gedacht, dass die Erinnerungen eines alten Gottes so gefährlich sind...?\n\nNun, Ihr solltet Euch wieder bei Soridormi melden und Euch an die Arbeit machen!", sourceObjective = "Meldet Euch bei Soridormi.", completion = "Wie Augermu sagte, mithilfe des Stundenglases könnt Ihr die verstörenden Visionen nun so oft betreten, wie Ihr wollt. \n\nEines noch: Wir haben einige Schlüsselerinnerungen in jeder der Visionen identifiziert. Durch sie könnt Ihr zusätzliche Gaben für diese spezielle Vision finden, mit denen Ihr länger dort verweilen und sie erkunden könnt.\n\nIch werde in der Herzkammer der Vision Beschreibungen hinzufügen, wie Ihr diese Gaben finden und freischalten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87337] = { id = 87337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großreinemachen", description = "Ve'nari hat alle Hände voll zu tun. In ihrer und Om'talads Abwesenheit werde ich Euch Eure Aufträge erteilen.\n\nWir beherbergen zahlreiche Geschöpfe hier in der Oase. Die hinterlassen Chaos. Macht Euch daran, es zu beseitigen.", sourceObjective = "Räumt in der Oase in K'aresh auf.", progress = "Das tut mir leid.", completion = "Ich muss mich für die Aufgabe entschuldigen, die mein Verwalter Euch gegeben hat. Gute Hilfe ist so schwer zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[87338] = { id = 87338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Schritte", description = "Wir haben einige der geretteten einheimischen Arten aus der Stasis geholt. Jetzt müssen wir ihre Habitate wiederherstellen. \n\nWir haben hier zwei Hauptarten sowie diese Konsole zur Überwachung der Arten in der Oase. Macht Euch mit diesen Kreaturen vertraut, bevor wir beginnen.", sourceObjective = "Stellt Euch den Tieren der Oase vor und überprüft ihren Status an der Konsole in der Oase.", progress = "Habt Ihr Euch mit den Tieren vertraut gemacht?", completion = "Ihr seid unversehrt. Wunderbar. Das heißt, dass wir schneller weitermachen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[87339] = { id = 87339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Routinearbeiten", description = "Ihr werdet zwar Aufgaben erhalten, die Euren Talenten entsprechen, doch gibt es auch zusätzliche Routinearbeiten, die in der Oase ständig anfallen.\n\nObwohl diese normalerweise von den Verwaltern übernommen werden, wäre ich für Eure Unterstützung durchaus dankbar, wenn Ihr in der Nähe seid. Sowohl jetzt als auch künftig.", sourceObjective = "Erledigt diverse Aufgaben in der Oase von K'aresh.", progress = "Habt Ihr hart gearbeitet?", completion = "Solltet Ihr den Verwaltern helfen wollen, gibt es immer Daten zu sammeln, Pflanzen zu gießen und Erde zu ebnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87340] = { id = 87340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Postwurfsendung", description = "Eine letzte Sache, bevor wir beginnen. Eine spezielle Aufgabe, die Euren einzigartigen Fähigkeiten entspricht.\n\nNein, nicht Töten. Fliegen. Die Oase braucht Spenden. Spenden kommen durch Werbung.\n\nNehmt diese Stapel Flugblätter und verteilt sie in Tazavesh.", sourceObjective = "Fliegt durch die Ringe über Tazavesh, um die Flugblätter zu verteilen.", progress = "Habt Ihr die Flugblätter verteilt?", completion = "Ich habe bereits mehrere Spendenanfragen erhalten. Fantastische Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[87341] = { id = 87341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Wenn Ihr nach Bier sucht, davon haben wir mehr als genug! Oder zumindest hätten wir das, wenn diese Dracthyr sich endlich beeilen würden, den Rest der Fässer herzubringen.\n\nEinige der Dracthyr sind hergekommen, um mit uns zu feiern und haben sich entschlossen, beim Transport des Biers zu helfen. Fässer rollen? So geht man doch nicht mit einem guten Gebräu um!\n\nWürdet Ihr mir zur Hand gehen und diese Fässer nach Klingenhügel bringen? Versucht aber bitte, sie nicht kaputt zu machen!", sourceObjective = "Liefert die Fässer in Klingenhügel ab.", progress = "Vorsichtig mit den Fässern! Gutes Bier sollte man nicht so durchschütteln.", completion = "Ich bin froh, diese Lieferung wohlbehalten zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[87342] = { id = 87342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer auf der Insel von Dorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[87343] = { id = 87343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Hohlfluch", description = "Die Streitkräfte der Schattenwache am Schattenpunkt haben sich um einen rätselhaften Champion namens Hohlfluch versammelt.\n\nAuch wenn die Existenz von Hohlfluch nicht bestätigt ist, haben wir ein Reiseportal des Champions ausfindig gemacht.\n\nÖffnet das Portal und findet Hohlfluch, damit wir ihn konfrontieren und vernichten können.", sourceObjective = "Kombiniert eine Schattenfassade, eine Energieverkapselung und eine Tasche mit Schleierscherben, um den Portalschlüssel zu fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87344] = { id = 87344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine große Bedrohung", description = "Tazavesh ist eine Stadt voller Unruhen, die von zahllosen Gefahren geplagt wird. Wir können Eure Hilfe stets gebrauchen.\n\nSeht Euch unsere Haftbefehlstafel an und überlegt Euch, ob Ihr das Zeug dazu habt, unsere größten Gefahren zu eliminieren.", sourceObjective = "Schließt einen Haftbefehl ab und eliminiert die Bedrohung für unsere Stadt.", progress = "Habt Ihr einen Haftbefehl abgeschlossen?", completion = "Gute Arbeit. Vergesst nicht, Euch auf der Haftbefehlstafel regelmäßig über neue Gefahren zu informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[87345] = { id = 87345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Xy'vox der Verrenkte", description = "Xy'vox der Verrenkte, ehemaliger Wachtmeister von Tazavesh, entstammt einer mächtigen Kartellfamilie.\n\nVielen ist nicht bewusst, dass die Familie durch illegale Verbrechen an Macht gewann und dabei bequemerweise von Xy'vox überwacht wurde.\n\nAls die Wahrheit ans Licht kam, tauchte Xy'vox unter. Ich glaube, der Wachtmeister hat die Stadt nie verlassen und versteckt sich stattdessen in der Menge, wo er weiter seinen Verbrechen nachgeht.\n\nFertigt einen Zufluchtdämpfer, um Xy'vox für alle in Tazavesh zu offenbaren.", sourceObjective = "Sammelt eine Tazaveshfassade, ein Astralsiegel und eine Zo'kitafrucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[87347] = { id = 87347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaumige Gebräue", description = "Verflixt! Es war womöglich ein Fehler, die Dracthyr um Hilfe bei diesen Lieferungen zu bitten. Sie haben die Bierfässer gerollt und sie überall zertrümmert! Aber wir sollten das Bier nicht verschwenden, wenn wir etwas tun können!\n\nNehmt ein Fass und steigt in den Himmel auf! Versucht, so viel Bier zu retten, wie Ihr könnt, indem Ihr die Blasen sammelt.", sourceObjective = "Sammelt Gebräublasen in Dun Morogh.", progress = "Habt Ihr das Fass aufgefüllt?", completion = "Vielen Dank für die Hilfe. Jetzt muss ich die Dracthyr nur noch überzeugen, die Fässer einfach herzufliegen, anstatt sie herumzurollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[87349] = { id = 87349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaumige Gebräue", description = "Es war womöglich ein Fehler, die Dracthyr um Hilfe bei diesen Lieferungen zu bitten. Sie haben die Bierfässer gerollt und sie überall zertrümmert! Aber wir sollten das Bier nicht verschwenden, wenn wir etwas tun können!\n\nNehmt ein Fass und steigt in den Himmel auf! Versucht, so viel Bier zu retten, wie Ihr könnt, indem Ihr die Blasen sammelt.", sourceObjective = "Sammelt Gebräublasen in Durotar.", completion = "Danke für die Hilfe. Jetzt muss ich die Dracthyr nur noch überzeugen, die Fässer einfach herzufliegen, anstatt sie herumzurollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[87354] = { id = 87354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reshanor der Ungebundene" }
quests[87355] = { id = 87355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in Heilsturz.", sourceObjectiveStatus = "unverified-source-field" }
quests[87356] = { id = 87356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in Azj-Kahet.", sourceObjectiveStatus = "unverified-source-field" }
quests[87357] = { id = 87357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in den Schallenden Tiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87358] = { id = 87358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenfassade", description = "Der Trick hinter einer perfekten Fassade ist, lebendige Schattenwachen zu scannen, und zwar mit einem raffinierten kleinen Gerät, das ich Euch gebe. Damit könnt Ihr die einzigartige Essenz kopieren, die den Kern ihres Seins ausmacht, und zur weiteren Verwendung speichern.\n\nIhr findet Schattenwachen im regulären als auch im ungebundenen Raum. Doch egal, wo Ihr sie findet, sie werden sich nicht über Eure Anwesenheit freuen, und sie wollen definitiv nicht gescannt werden.", sourceObjective = "Scannt 18 Schattenwachenessenzen.", progress = "Habt Ihr die Scans durchgeführt?", completion = "Gute Arbeit! Ist nicht jeden Tag, dass jemanden mit einem vollen Scanner zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87363] = { id = 87363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazaveshfassade", description = "Für die perfekte Tazaveshfassade müsst Ihr lebendige Schattenwachen im Bereich von Tazavesh scannen, und zwar mit einem Gerät, das ich Euch gebe.\n\nDamit könnt Ihr die Ziele markieren, um die einzigartige Essenz zu kopieren, die den Kern ihres Seins ausmacht, und sie zur weiteren Verwendung speichern.\n\nDas ist ganz schön gefährlich, da Ihr direkt auf sie zugehen müsst, um zu sehen, ob sie gewillt sind, gescannt zu werden!", sourceObjective = "Scannt 15 Schattenwachenessenzen.", progress = "Habt Ihr die Scans durchgeführt?", completion = "Die kriminellen Elemente von Tazavesh lassen sich nur ungern scannen. Kommt nicht jeden Tag vor, dass jemand mit einem vollen Scanner zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87374] = { id = 87374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "C.H.E.T.T.-In", description = "<Ihr bemerkt, wie Eure Taschen sich plötzlich etwas schwerer anfühlen, während Ihr einen flüchtigen Blick auf eine schattenhafte Gestalt erhascht, die sich von Euch wegbewegt.\n\nEine kurze Suche enthüllt eine Karte, die Euch nicht bekannt vorkommt.\n\nAuf der einen Seite steht lediglich \"C.H.E.T.T.!\". Auf der anderen Seite befindet sich eine vereinfachte Karte von Lorenhall mit einer Wegbeschreibung, die zum ersten Stock im Hotel Inkontinental führt.>", sourceObjective = "Sprecht mit C.H.E.T.T. im ersten Stock im Hotel Inkontinental, um von C.H.E.T.T.-Listen zu erfahren.", completion = "<Unsicher, ob Ihr nun mehr oder weniger über diese geheimnisvolle Maschine wisst, setzt Ihr Eure Abenteuer mit neuen Möglichkeiten zu Eurer Verfügung fort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[87376] = { id = 87376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astralsiegel", description = "Ein Astralsiegel gewährt uneingeschränkten Zugriff und Kontrolle über astrale Anlagen, ohne Verdacht zu wecken.\n\nEin authentisches Siegel zu erhalten, kann ganz schön schwierig sein. Es ist deutlich einfacher, eins aus weggeworfenen Chiffren zu fälschen.\n\nWenn Ihr kein Problem damit habt, Euch die Finger schmutzig zu machen, dann könnt Ihr solche weggeworfenen Schriftstücke in den Müllhaufen außerhalb der Stadt finden. Bringt sie mir, dann kann ich ein Siegel für Euch fertigen.", sourceObjective = "Sammelt 12 weggeworfene Schattenschriftstücke.", progress = "Konntet Ihr die Schattensiegel finden?", completion = "Oh, die sind gut. Damit sollte ein Siegel leicht herzustellen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[87380] = { id = 87380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zo'kitafrucht", description = "Ihr könnt die Frucht haben, doch zuerst müsst Ihr mir einen Gefallen tun.\n\nEtwas beobachtet uns. Ihr könnt es nicht sehen, doch das Aroma der Frucht zieht es zu uns. Verborgene Monster die außerhalb unseres Sichtfelds lauern.\n\nVerschafft Euch Zugang zum ungebundenen Raum, jagt diese Kreaturen und bringt mir ihre Häute. Ich möchte Beweise, dass diese Kreaturen wirklich existieren!", sourceObjective = "Sammelt 8 ungebundene Tierhäute.", progress = "Habt Ihr sie gesehen? Habt Ihr sie in Stücke geschnitten?", completion = "Ich wusste, dass es sie gibt, und habe jetzt diese fabelhaften Häute als Beweis! Hier habt Ihr wie versprochen die Frucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[87404] = { id = 87404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieverkapselung", description = "Ihr braucht eine Energieverkapselung? Dann habt Ihr wohl vor, ein Portal oder einen Teleporter zu aktivieren!\n\nNichts leichter als das, vorausgesetzt, Ihr besorgt mir die nötige Energie.\n\nSchaut bei den Erntern in der Nähe nach. Sie geben uns, was wir brauchen, solange wir helfen, die Wyrms von den Erntern fernzuhalten.", sourceObjective = "Sammelt 10 Energie von den Energieerntern und knisternden Wyrms.", progress = "Habt Ihr die benötigte Energie?", completion = "Eine einfache Aufgabe, doch eine, die ich sehr befriedigend finde. Letztendlich ist die Energie schließlich der fundamentale Antrieb all unserer Arbeit hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[87405] = { id = 87405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Schmuddler", description = "Ein gewaltiger Wurm wurde in den Treibschrottsanden östlich der Stadt gesichtet. Die Anwohner haben ihm den Spitznamen Schmuddler gegeben.\n\nLeider haben wir Stellvertreter Zo'wie verloren, als er der Sache nachgehen wollte. Die Kreatur hat ihn unter die Oberfläche gezogen.\n\nFindet einen Weg, den Wurm dazu zu bringen, sich zu zeigen, damit wir ihm endgültig den Garaus machen können.", sourceObjective = "Sammelt einen Korb mit Zo'kitafrucht, ein Dutzend Schleierscherben und einige aromatische Reste.", sourceObjectiveStatus = "unverified-source-field" }
quests[87406] = { id = 87406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inaktiver Megamechagorilla", description = "<Trotz Eurer besten Bemühungen bleibt die Maschine stumm.\n\nVielleicht könnte ein hiesiger Experte sie zum Laufen bringen.>", sourceObjective = "Bringt den inaktiven Megamechagorilla zu Ditty Zündknabe zur Reparatur.\n\nBereitgestellter Gegenstand:", completion = "Eine Gorillion-Einheit! Wo habt Ihr die denn aufgetrieben?\n\nFunktionsunfähig? Wahrscheinlich nur ein paar lose Kabel.\n\nEinmal kräftig schütteln... diesen Schalter umlegen... und schon ist er wie neu!", sourceObjectiveStatus = "unverified-source-field" }
quests[87408] = { id = 87408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz der Vergangenheit", description = "Wir haben die Erschaffung existierender Kreaturen perfektioniert, aber ich will noch einen Schritt weiter gehen. Ich würde diesen Prozess gern mit einer Kreatur ausprobieren, die das Verschlingen nicht überlebt hat. \n\nIn dieser Welt lebte einst eine Kreatur namens K'arroc. Findet ihre Essenz und sammelt sie für mich.", sourceObjective = "Sammelt 15 Gleiteressenz im ungebundenen Raum von K'aresh.", progress = "Habt Ihr die Essenzen gesammelt, die ich brauche?", completion = "Wenn das funktioniert, wird es das Fantastischste sein, was ich je erreicht habe! Die Wiederbelebung einer ausgestorbenen Spezies.", sourceObjectiveStatus = "unverified-source-field" }
quests[87409] = { id = 87409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Tod, Leben.", description = "Jetzt müssen wir die Maschine nur noch ihre Arbeit machen lassen. \n\nIch überlasse Euch die Ehre. Wenn es schiefgeht, werde ich Euch die Schuld dafür geben.\n\n... Das war nur ein Witz. Größtenteils.", sourceObjective = "Helft Ve'nari dabei, mit ihrer Maschine Leben in der Oase zu erschaffen.", completion = "Erfolg... Versteht Ihr, was das bedeutet, {name}? Wir sind nicht mehr auf die Kreaturen beschränkt, die wir mitgenommen haben. Solange wir ihre ungebundenen Gegenstücke finden können, können wir K'areshs Kreaturen neu erschaffen. Sie werden wieder leben!", sourceObjectiveStatus = "unverified-source-field" }
quests[87410] = { id = 87410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagfeste Verhandlungen", description = "Die K'arrocs sind groß und werden früher oder später ihre Flügel ausbreiten. Vielleicht sollten wir uns darauf vorbereiten, was? \n\nDie Schattenwache hat alle möglichen Leerenschilde. Ich wette, Ihr könntet Teile davon beschaffen, wenn Ihr Eure üblichen Methoden der Verhandlung mit Feinden einsetzt. Bringt die Teile zu Ve'nari, sobald Ihr fertig seid.", sourceObjective = "Sammelt 12 Leerenschildteile in der Umbragarnison.", progress = "Habt Ihr die Teile besorgt?", completion = "Wie clever von Hemet. Ein tiergestützter Leerenschild ist eine hervorragende Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[87411] = { id = 87411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Baukunst", description = "Ich schätze, dass wir den Leerenschild bauen können, den Hemet sich vorgestellt hat, aber diese Teile sind nicht ideal. Trefft mich außerhalb der Oase im Osten, und wir werden sehen, ob wir eine brauchbare Lösung finden.", sourceObjective = "Helft Ve'nari außerhalb der Oase dabei, einen Leerenschild herzustellen.", progress = "Kommt schon, lasst uns mit dem Bau beginnen.", completion = "Meinen Vorbehalten zum Trotz scheinen wir jetzt doch einen brauchbaren tragbaren Leerenschild zu haben. Hervorragende Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[87412] = { id = 87412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "K'arrocische Fotos", description = "Wir müssen unsere Dokumentation auf dem neuesten Stand halten. Das bedeutet, dass ich erneut Eure Dienste brauche. \n\nNehmt diese Kamera und macht noch mehr Fotos von den K'arrocs. Ihr findet sie auf den Felsen in der Gegend.", sourceObjective = "Dokumentiert 7 beherrschende K'arrocs.", progress = "Habt Ihr die Fotos gemacht, um die ich gebeten habe?", completion = "Sie sind großartig. Das wird eine große Hilfe für unsere Forschung sein. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[87413] = { id = 87413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelbad", description = "{name}! Genau nach Euch habe ich gesucht! Die K'arrocs verdrecken so sehr, dass es ihren natürlichen Geruch überdeckt. Es gibt hier nicht genug Wasser, damit sie sich baden können!\n\nNehmt diesen Animasauger. Der wird den Dreck ganz einfach einsaugen, aber Ihr müsst Euch mit denen am Boden begnügen. Versucht es mal auf den Felsen im Norden!", sourceObjective = "Wascht 7 beherrschende K'arrocs.", completion = "Ah, ich kann es schon im Wind riechen. Habt vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[87414] = { id = 87414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizinische Manöver", description = "Es wäre gut, die K'arrocs einmal einer gründlichen medizinischen Untersuchung zu unterziehen. \n\nKönntet Ihr sie schrumpfen und zu mir bringen?", sourceObjective = "Schrumpft und sammelt 8 beherrschende K'arrocs.", progress = "Habt Ihr die K'arrocs, nach denen ich Euch gefragt habe, zusammengetrieben?", completion = "Ah, die sehen gut aus. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[87415] = { id = 87415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel über K'aresh", description = "Das Schildgerät, bei dem Ihr geholfen habt, wurde erprobt. Es ist bereit, flügge zu werden, wenn man so will.\n\nSprecht mit Om'torid. Er hat bereits eine Strecke für Euren Flug mit dem K'arroc ausgesucht.", sourceObjective = "Probiert das Schildgerät aus, indem Ihr außerhalb der Oase auf einem K'arroc fliegt.", progress = "Wie hat der Schild sich geschlagen?", completion = "Wie fühlt es sich an, der Erste in einem Jahrtausend zu sein, der auf dem Rücken eines K'arroc geflogen ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[87417] = { id = 87417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Dungeons", description = "Die Feinde von Khaz Algar erheben sich, geeint in ihrem Ziel, Leid über alle zu bringen, die nicht an ihre Sache glauben.\n\n<Faerin hält inne, wirft dann einen kurzen Blick auf den Tisch vor ihr, bevor sie ihren Blick wieder zu Euch wendet.>\n\nZeigt diesen Leuten das Licht, {name}. Wenn sie den Irrtum ihrer Wege nicht erkennen, bereitet ihren Überzeugungen bitte ein gnädiges Ende.", sourceObjective = "Schließt einen beliebigen saisonalen Dungeon auf Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Danke, dass Ihr dem Volk von Khaz Algar einen Hoffnungsschimmer bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87419] = { id = 87419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Tiefen", description = "In diesen Landen gibt es viele tiefe Spalten, in deren Schatten unsere Feinde sich in falscher Sicherheit wiegen. Erkundet diese verborgenen Orte und lasst unseren Gegnern keine Zuflucht.", sourceObjective = "Schließt eine Tiefe von The War Within auf einem beliebigen Schwierigkeitsgrad ab.", completion = "Dank Eurer Mühe gibt es nun weniger Schatten in der Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87420] = { id = 87420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korb mit Zo'kitafrucht", description = "Ihr braucht mehr Zo'kitafrüchte als ich hier je aufzubewahren wagen würde! \n\nSchon eine Zo'kitafrucht ist genug, um meinen Bruder aus dem Geschäft zu verdrängen und Ihr bittet um einen ganzen Korb? \n\nGanz schön gewagt!\n\nBesucht Biokuppel: Primus. Dort baue ich sie heimlich an, wo sie niemand sieht. Verwendet meine Pflückausrüstung, um sie zu orten, und nehmt Euch so viele Ihr braucht.", sourceObjective = "Sammelt 8 frisch gepflückte Zo'kitafrüchte.", progress = "Habt Ihr genug bekommen?", completion = "So viele Zo'kitafrüchte! Schnell, packt sie in einen Korb und verschwindet, bevor der Geruch unsere Kunden um ihr Leben rennen lässt!", sourceObjectiveStatus = "unverified-source-field" }
quests[87422] = { id = 87422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Weltquests von Lorenhall", description = "Lorenhall mag zwar ein Ort sein, den ich nicht verstehe, aber auch seine Bewohner brauchen Hilfe. Unsere Konflikte verschlimmern ihre Situation, und es wäre gut, ihnen dabei zu helfen, einen Ausweg zu finden.\n\nGeht und helft ihnen. Findet heraus, was Ihr tun könnt, damit diese... Kartelle... sich näher kommen... und uns.", sourceObjective = "Schließt Weltquests in Lorenhall ab.", completion = "Ihr habt Euch außergewöhnliche Mühe bei einigen... einzigartigen Aufträgen gegeben. Euer Dienst an Lorenhall wird von allen sehr geschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87423] = { id = 87423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Forscher von Lorenhall", description = "Lorenhall wird durch eine komplexe Mischung aus Innovation, harter Arbeit, Treue und offenbar auch dem schieren Willen der Goblins zusammengehalten. Anstatt sich in ihrer sonnenlosen Höhle zu verstecken, haben die Goblins eine Stadt errichtet, die von Bewegung und Aktivität angetrieben wird. Wir können vieles von ihnen lernen.\n\nNachdem wir über Jahre keine neuen Gesichter gesehen haben, bringen sie neues Licht in unser Land. Geht und helft Ihnen, wie auch immer Ihr Euch nützlich machen könnt.", sourceObjective = "Schließt verschiedene Aktivitäten in Lorenhall ab.", progress = "Sie verharren nicht, nur weil etwas nicht funktioniert. Ich bewundere das.", completion = "Als Beledar sich verdunkelte, was hätten sie gebaut, wenn sie an unserer Stelle gewesen wären?\n\nEure Mühen sind weiterhin von großem Nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87424] = { id = 87424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Weltbosse", description = "Heilsturz ist nicht das einzige Land, das von Feinden heimgesucht wird.\n\nGroße Monster bedrohen unsere Verbündeten. Wo auch immer die Schatten des Krieges sich senkten, erheben sich wilde Tiere und intelligente Unholde. Sie töten Arathi, Irdene und alle anderen, die zu uns stehen. Von unschuldigen Bauern bis zu großen Kriegern.\n\nIch weiß, die Heilige Flamme brennt in Euch. Ihr seid unsere beste Hoffnung bei der Jagd auf diese großen Übel.", sourceObjective = "Bezwingt alle verfügbaren Weltbosse in The War Within.", completion = "Wie ist es Euch ergangen? Irgendwelche neuen Narben? Oder neue Geschichten zu erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[87425] = { id = 87425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große, klebrige Leerenmasse", description = "Ah, ja, ich habe gesehen, was Ihr beschreibt!\n\nDas Harz der verderbten Pflanzen ist mit Leerenenergie erfüllt. Sammelt so viele Proben Ihr könnt. Ich mache daraus dann eine große, klebrige Masse.", sourceObjective = "Sammelt 5 Einheiten verderbtes Harz.", progress = "Habt Ihr das Harz gefunden?", completion = "Alles, was die verderbten Pflanzen ausmerzt, kommt unseren Bemühungen hier entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87426] = { id = 87426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aromatische Reste", description = "In diesen Sanden gibt es allerlei Möglichkeiten, Profit zu machen, doch hütet Euch vor dem Monster.\n\nEs ist hungrig... und ich habe gesehen, wie es Plünderer unter den Sand gezogen hat!\n\nAber man kann es reinlegen. Ich habe es mal gefüttert; ihm einige Reste zugeworfen.\n\nIhr braucht den leckersten Müll, um es anzulocken. Sammelt, was Ihr so finden könnt, dann helfe ich Euch, die aromatischsten Essensreste rauszusuchen.", sourceObjective = "Sammelt 24 weggeworfene Essensreste.", progress = "Konntet Ihr was Leckeres finden?", completion = "Ich habe die leckersten Stücke rausgesucht. Damit sollten wir die Aufmerksamkeit des Monsters erregen!", sourceObjectiveStatus = "unverified-source-field" }
quests[87475] = { id = 87475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfall der Sureki: Haltet die Mauer", description = "Flammen! Diese Chitinbiester sind gnadenlos!\n\nWir haben Berichte von Auralia Stahlstoß über eine kleine Streitmacht an Nerubern erhalten, die vor der Stadt für Ärger sorgen.\n\nSchließt Euch unseren Verbündeten in den Außenbezirken von Mereldar an und unterstützt sie im Kampf!", sourceObjective = "Helft den Strahlen der Flame, die Sureki vor Mereldar zurückzuschlagen.", progress = "Wir müssen die Stellung gegen diese Sureki halten. Schlagt sie zurück!", completion = "Exzellente Arbeit, {name}. Unsere Verstärkung wird von hier an übernehmen.\n\nMyltons Berichte wiesen auf eine weitaus größere Streitmacht westlich der Ehrengründe hin, daher müssen wir wachsam bleiben und diese Mauern halten.\n\nMöge die Heilige Flamme Eure Klinge lenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[87477] = { id = 87477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfall der Sureki: Südlicher Schwarm", description = "Diese Sureki sind nicht gerade dafür bekannt, ihre Offensive so schnell aufzugeben.\n\nBerichte von unseren südlichen Vorposten warnen vor einem Schwarm, der sich entlang der Bergkette regt.\n\nIch weiß nicht, ob sie Tenirs Aufstieg oder Beledars Schatz angreifen wollen, aber wir dürfen nicht zulassen, dass sie als erste zum Zuge kommen.\n\nSchließt Euch unseren Verbündeten an und fangt den Schwarm ab!", sourceObjective = "Helft den Strahlen der Flamme, den Schwarm der Sureki im südlichen Heilsturz zurückzuschlagen.", progress = "Die Neruber haben jeden verdorbenen, vielbeinigen Schrecken der Tiefe mit diesem Schwarm hervorgebracht!\n\nWir dürfen nicht zulassen, dass unsere Vorposten fallen!", completion = "Lady Faerin hatte recht mit Euch, {name}. Wir schulden Euch Dank.\n\nIhr habt Tenirs Aufstieg und Beledars Schatz wertvolle Zeit verschafft.\n\nAb hier übernehmen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[87480] = { id = 87480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfall der Sureki: Der Sturmangriff im Osten", description = "Keine Zeit zum Ausruhen, {name}!\n\nUnsere Verbündeten bei den Irdenen im östlichen Teil von Heilsturz haben ein Bataillon der Sureki entdeckt, das sich auf einen Angriff auf Dunelles Güte vorbereitet. Sie müssen es auf den Dämmerturm abgesehen haben!\n\nVerstärkungen der Strahlen der Flamme sichern gerade die Stadt und Lothars Landung.\n\nEilt nach Osten und leistet alle Hilfe, die Ihr vermögt!", sourceObjective = "Unterstützt die Strahlen der Flamme und vereitelt den Angriff der Sureki im Osten.", progress = "Wir werden diese Stellung halten. Los, helft Dunelles Güte weiter unten!", completion = "Die Bewohner von Dunelles Güte danken Euch, {name}.\n\nWir werden Lothars Landung gemeinsam mit unseren Verbündeten bei den Irdenen halten und die Stadt darunter befestigen.\n\nMöge das Licht der Heiligen Flamme stets mit Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[87496] = { id = 87496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorteilspakete", description = "Das sind schwere Zeiten, also haben die Kartelle es mit dieser neuen Geschäftsstrategie versucht, die sie \"Mitarbeiterbindung\" nennen. Ich hab noch nie davon gehört, aber es klingt wichtig.\n\nNun, ich bin sicher, das bedeutet, dass die Angestellten das Privileg bekommen, Sachen aus den Geschäften der Firma einkaufen zu dürfen, wenn man lang genug für sie gearbeitet hat.\n\nFindet heraus, was die Kartelle zu verkaufen haben. Schaut, ob Euch etwas davon gefällt, bevor Ihr anheuert.", sourceObjective = "Besucht alle Rüstmeister der Kartelle in Lorenhall.", progress = "Ihr könnt die Verkäufer in den Hauptquartieren der jeweiligen Kartelle finden.", completion = "Sie haben eine ziemlich nette Auswahl, oder nicht?\n\nWenn Ihr je Hilfe braucht, um sie wiederzufinden, lasst es mich wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87546] = { id = 87546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haftbefehl: Lila Torf", description = "Bei der Wiederherstellung der Biokuppeln wurden viele der kontaminierten Pflanzen entfernt, um dem Boden Gelegenheit zu geben, zu heilen.\n\nEin verderbter Peitscher ist uns jedoch entronnen. Die Kuppeltechniker nennen ihn \"Lila Torf\" und er breitet seine Wurzeln und Samen weiter in Biokuppel: Primus aus.\n\nDie Pflanze versteckt sich in einer alten Stasiszelle außerhalb der Kuppel. Konstruiert ein Gerät, mit dem Ihr die schützende Zelle entfernen und der Pflanze den Garaus machen könnt.", sourceObjective = "Kombiniert eine große, klebrige Leerenmasse, eine Energieverkapselung und eine ungebundene Batterie, um einen Schlüssel zu erschaffen, mit dem Ihr die Stasiskugel aufschließen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87547] = { id = 87547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Die Dracheninseln sind ein gefährlicher und unerforschter Ort. Wir müssen Euch gut vorbereiten.\n\nIhr seid nun stark genug, um eine Kampfspezialisierung zu wählen.\n\nDamit schaltet Ihr eine Reihe neuer Fähigkeiten frei, um Euch den Gefahren dieses Ortes zu stellen.\n\nWählt jetzt Eure Kampfspezialisierung.", sourceObjective = "Wählt Eure Kampfspezialisierung.", completion = "Ausgezeichnete Wahl! Ich freue mich schon darauf, was Ihr als nächstes tut.\n\nNehmt dieses Reittier. Er wird Euch helfen, schneller voranzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87548] = { id = 87548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dutzend Schleierscherben", description = "Ja, ich weiß von den Schleierscherben. Sie sind ein gefragter Schatz, nach dem viele Diebe trachten! Doch keine Sorge, der rechtschaffene Om'sto würde sich nie auf solche Verbrechen einlassen.\n\nWenn Ihr auf Schleierscherben aus seid, dann sucht einfach nach den Ratten dieser Stadt, das sind die listigsten Diebe überhaupt!\n\nFolgt einem diebischen Huscher zu seinem Bau, dort solltet Ihr unter seiner Diebesbeute auch einen Edelstein finden. Bringt mir, was Ihr finden könnt, dann packen wir Euch ein hübsches Dutzend zusammen.", sourceObjective = "Sammelt 12 gestohlene Schleierscherben.", progress = "Seid Ihr den Ratten gefolgt?", completion = "Wie ich sehe, waren das städtische Ungeziefer kein Problem für Euch. Dieses Dutzend sollte eine interessante Form bilden. Ich packe sie für Euch zusammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[87550] = { id = 87550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woche 2: Wir kommen richtig in Fahrt", description = "Es ist die zweite Woche der Durchtriebenen Duos! Doppelte Brutalität, doppelter Spaß! Gewinnt diese Woche eine Runde und erhaltet noch mehr Belohnungen!", sourceObjective = "Gewinnt eine Runde gegen Durchtriebene Duos und sprecht anschließend mit Vinnie Naschkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[87551] = { id = 87551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woche 3: Verbreitet die Kunde", description = "Hey, wollt Ihr der Organisation aushelfen? Also, die frohe Kunde verbreiten und so? Wenn Ihr das nächste Mal in einer Runde seid, dann präsentiert Euer durchtriebenes Banner in der Arena. Bekennt Farbe!\n\nAber seid vorsichtig... Das könnte Euren Kontrahenten überhaupt nicht schmecken und Ihre Aufmerksamkeit auf Euch ziehen...Ihr erlernt:", sourceObjective = "Platziert Euer durchtriebenes Banner während einer Runde und gewinnt diese anschließend.", sourceObjectiveStatus = "unverified-source-field" }
quests[87552] = { id = 87552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woche 4: Sie haben von Euch gehört", description = "Ihr macht Euch einen Namen, {race}. Fahrt weiter Siege ein, dann verkaufe ich weiter Tickets.", sourceObjective = "Gewinnt eine Runde gegen Durchtriebene Duos und sprecht anschließend mit Vinnie Naschkatze.", completion = "Ihr kämpft mit Stil! Ihr solltet an Eurer Signatur arbeiten... Ich habe gehört, dass einige der Zuschauer einen Fanklub für Euch gründen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87553] = { id = 87553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woche 5: Eine weitere hervorragende Woche!", description = "<Vinnie ist mit Geldzählen beschäftigt.>\n\nWas? Oh, hey, {name}. Seid Ihr hier, um Sitzplätze zu verkaufen... ich meine... seid Ihr für eine weitere Runde hier? Klasse!", sourceObjective = "Gewinnt eine Runde gegen Durchtriebene Duos und sprecht anschließend mit Vinnie Naschkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[87554] = { id = 87554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woche 6: Das Finale!", description = "Das war's, das Ende der Reise. Verabschieden wir uns mit einem Brüllen!\n\nZeigt ein letztes Mal eine gute Vorstellung, dann können wir zusammen unser Geld zählen!", sourceObjective = "Gewinnt eine Runde gegen Durchtriebene Duos und sprecht anschließend mit Vinnie Naschkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[87555] = { id = 87555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo man seine Ruhe hat", description = "Bevor Ihr aufbrecht, solltet Ihr Euch einen Ruhestein besorgen.\n\nDieser kleine Stein wird Euch in das Gasthaus bringen, an das Ihr ihn zuletzt gebunden habt.\n\nEs ist nicht wirklich ein Gasthaus, aber die Forscher haben ein Zelt eingerichtet.\n\nProbiert doch Euer neues Reittier aus und reitet rüber zum Fröhlichen Hal. Er wird Euch mit einem Ruhestein versorgen.", sourceObjective = "Reitet Euer Reittier und sprecht mit dem Fröhlichen Hal, um einen Ruhestein zu bekommen, der an die Wilde Küste gebunden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[87562] = { id = 87562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Dracheninseln", description = "Es ist an der Zeit, dass sich unsere Wege trennen. Ich muss mich weiter im Inneren der Dracheninseln an einem Ort namens Azurblaues Gebirge dringenderen Angelegenheiten widmen.\n\nToddy Schnurrbart von der Drachenschuppenexpedition könnte Eure Hilfe gebrauchen.\n\nGute Reise, {name}. Ich freue mich auf unser nächstes Treffen!", sourceObjective = "Trefft Euch mit Toddy Schnurrbart, um Euer Abenteuer auf den Dracheninseln zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[87569] = { id = 87569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesetzlich vorgeschriebene Pause" }
quests[87581] = { id = 87581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Herumgelaufe mehr", description = "Wir müssen etwas dagegen tun, dass Ihr so lange braucht, von A nach B zu kommen. Zum Glück kenne ich genau die Richtige. Trefft Euch mit Omi Talullah bei Versand & Logistik und fragt sie, ob sie Euch einen fahrbaren Untersatz leihen kann.", sourceObjective = "Trefft Omi Talullah im zweiten Stock von Versand & Logistik.", completion = "Ihr braucht ein Auto? Natürlich haben wir ein Auto für Euch! Wir haben so viele Autos! Hier, ich habe sogar ein paar Ersatzschlüssel dabei!", sourceObjectiveStatus = "unverified-source-field" }
quests[87582] = { id = 87582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Sitz des Wahnsinns", description = "He, da. Südlich von Gossenheim passieren einige ganz schön seltsame Dinge.\n\nEinige meiner Freunde sind verschwunden, und ihre Familien machen sich Sorgen um sie. Wie wär's, wenn Ihr Eure Machereinstellung da runter schafft und herausfindet, was passiert ist?\n\n<Paks kratzt sich am Kinn, bevor er Euch ernst ansieht.>\n\nIch bin sicher, es wird irgendeine Vergütung für Eure Mühen geben. Vertraut mir.", sourceObjective = "Schließt die Tiefe von Ausgrabungsstätte 9 auf beliebigem Schwierigkeitsgrad ab.", progress = "Jo, habt Ihr rausgefunden, was da unten passiert ist?", completion = "He, ich bin Euch wirklich dankbar, dass Ihr da runter geht und die Sache erledigt.\n\nIch habe mit der Freunde-Geschichte gelogen, aber wenigstens werdet Ihr bezahlt, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[87583] = { id = 87583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Die Läuse in der Schleuse.", description = "Ah, {class}. Einige Düsternisverschmolzene haben sich in der Kanalisation hier in Lorenhall angesiedelt. Sie ziehen hart arbeitenden Goblins das Geld aus der Tasche, klauen ihnen die Brotzeit und manchmal zerstören sie sogar die Zierflamingos in ihren Gärten!\n\nDiese Düsternisverschmolzenen haben wirklich keinen Anstand, das sage ich Euch.\n\nIch weiß, dass Ihr das Richtige tun und uns aushelfen werdet. Vor allem nach so einer herzzerreißenden Geschichte.", sourceObjective = "Schließt die Tiefe der Seitenstraßenschleuse auf beliebigem Schwierigkeitsgrad ab.", progress = "Habt Ihr die Düsternisverschmolzenen schon rausgeworfen?", completion = "He, dank Euch können sich alle Flamingos in Lorenhall nachts jetzt sicher fühlen.\n\nIhr seid echt korrekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[87588] = { id = 87588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kloppt den Schrott" }
quests[87597] = { id = 87597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Tasche mit Schleierscherben", description = "Ich würde Euch ja einfach selbst Schleierscherben verkaufen, aber mein Vorrat wurde geplündert. Das Ungeziefer der Stadt lässt sich keine Chance entgehen, sie mir zu stibitzen, wann immer ich ihnen den Rücken zudrehe.\n\nFolgt einem diebischem Huscher zu seinem Nest, und schon solltet Ihr einige gestohlene Scherben finden.\n\nUm Euch zu helfen, gebe ich Euch ein Gerät, mit dem Ihr dieses diebische Ungeziefer aufspüren könnt. Bringt genug gestohlene Schleierscherben für uns beide zurück.", sourceObjective = "Sammelt 18 von Om'stos Schleierscherben.", progress = "Habt Ihr die Schleierscherben gefunden?", completion = "Ah, ich wusste, dass auf Euch Verlass ist! Der rechtschaffene Om'sto glaubt allmählich, dass Ihr gut fürs Geschäft seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[88652] = { id = 88652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichtslosenmaske der Nemesis", description = "Es gibt Gegner, die man im Kampf besiegt, und solche, gegen die man stets aufs Neue Krieg führt. Man hält sie für besiegt, doch sie kehren aus den Schatten zurück und greifen immer wieder an. So definiert sich eine Nemesis: Als Erzfeind, der ewig lebt, egal, was man unternimmt.", sourceObjective = "Bringt die Gesichtslosenmaske der Nemesis in einer verstörenden Vision zum Altar zurück.", progress = "Legt die Gesichtslosenmaske der Nemesis auf den Altar.", completion = "Das Anerkennen Eurer Nemesis ist der erste Schritt in Richtung ihrer endgültigen Niederlage. Doch sie wäre keine solche, wenn sie nicht unzählige Wege fände, um erneut gegen Euch anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[88655] = { id = 88655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in die Scherbenwelt", description = "Schlangen! Warum mussten es Schlangen sein?\n\nVe'nari sagt, dass es auf K'aresh vor der Verschlingung schlangenartige Wesen gab. Keines davon hat überlebt. Sie haben immer noch Würmer, aber sie sind es nicht, worauf wir aus sind.\n\nIch kenne genau den richtigen Ort. Mein altes Revier in Nagrand in der Scherbenwelt.\n\nDiese höllische Portalvorrichtung wird uns dorthin bringen.", sourceObjective = "Stoßt zu Hemet Nesingwary bei Nesingwarys Safari in Nagrand in der Scherbenwelt.", completion = "Schön zu sehen, dass Ihr es Euch nicht anders überlegt habt. Los, schnappen wir uns ein paar Schlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88656] = { id = 88656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuschelsteine", description = "Nun gut. Wir werden ein paar Dinge sammeln müssen, damit die Schlangen sich auf K'aresh wohlfühlen. Beschaffen wir ihnen ein paar Betten.\n\nSteine gehören dabei zu den wichtigsten Dingen! Schlangen können sich auf Felsen sonnen oder sich darunter verstecken.\n\nDie Erdelementare in der Nähe waren uns immer ein Dorn im Auge. Schaut nach, ob Ihr ein paar Steine von ihnen beschaffen könnt.", sourceObjective = "Sammelt 20 glatte Steine von gequälten Erdgeistern, wütenden Zermalmern oder zerbrochenen Rumplern.", progress = "Es ist ganz nett, diesen Kreaturen zu helfen, anstatt sie zu jagen.\n\nDie wütenden Elementare zählen nicht!", completion = "Das sollte reichen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[88657] = { id = 88657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zangarmoos", description = "Als Nächstes brauchen wir Moos für ihre Betten. So leid es mir tut, wir werden dafür in den schleimigen Sumpf gehen müssen.\n\nDie Naga kontrollieren diesen Ort. Es wächst auf ihren Pilzbäumen. Sie knabbern gern daran, oder anderen Ekelhaftigkeiten.\n\nDer schnellste Weg nach Zangarmarschen ist über den Pass im Norden. Ich an Eurer Stelle würde mich an der Küste der Dunkelkämme umschauen.", sourceObjective = "Sammelt 15 Sumpfmoos in Zangarmarschen.", progress = "Wie viel habt Ihr besorgt? Das sind mit die letzten Dinge, die wir brauchen, bevor wir nach K'aresh zurückkehren.", completion = "Ich bin froh, dass Ihr es in einem Stück zurückgeschafft habt. Und gerade rechtzeitig. Der alte Fitz und ich wehren schon seit gefühlten Ewigkeiten die Angriffe dieser verrückten Talbuks ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[88658] = { id = 88658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen und Pflanzen", description = "Natürlich brauchen wir auch ein paar Schlangen. Das ist der Grund, weshalb wir überhaupt hier draußen sind.\n\nIhr findet die kleinen, die wir brauchen, im Telaaribecken südlich von hier. Stöbert einfach an ihren Höhlen und sie kommen herausgekrochen. Dort wachsen die Pflanzen, die sie mögen.\n\nWo wir schon dabei sind, besorgt auch gleich ein paar dieser duftenden Pflanzen. Ihr wisst das vielleicht nicht, aber Schlangen haben einen hervorragenden Geruchssinn.", sourceObjective = "Sammelt 10 Nagrandschlangen und 20 duftende Traumwinde.", progress = "Wie viele habt Ihr? Ich hab keine Ahnung, Eure Tasche sieht immer randvoll aus.", completion = "Wir müssen dafür sorgen, dass die Schlangen es so bequem haben wie möglich, wenn wir sie nach K'aresh bringen.\n\nAber was zur Hölle! Oh, der Geruch dieser Pflanzen. Welch ein Duft!", sourceObjectiveStatus = "unverified-source-field" }
quests[88659] = { id = 88659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr gemütliche Betten", description = "Wir brauchen für Verschiedenes Ersatz - Steine und Moos für die Betten und mehr von diesen stinkenden Blumen.\n\nVergesst nicht, Ihr bekommt die Steine von den Erdelementaren in Nagrand. Die Pflanzen wachsen ebenfalls in Nagrand, im Telaaribecken. Und das Moos findet Ihr an der Küste der Dunkelkämme in Zangarmarschen.\n\nDas ist für mich ein guter Vorwand, mal wieder meine Freunde zu besuchen. Wir sehen uns auf der anderen Seite des Portals.", sourceObjective = "Sammelt 10 Duftende Traumwinde, 10 Sumpfmoos und 10 Glatte Steine in Nagrand und Zangarmarschen in der Scherbenwelt.", progress = "Habt Ihr alles?", completion = "Danke, {name}. Das wird seinen Zweck erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88660] = { id = 88660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen im Flugzeug", description = "Zu guter Letzt müssen wir diese zwei Schlangen aus meinem Flugzeug rauskriegen!\n\nIch weiß nicht, wie lange Schlangen normalerweise leben, aber diese zwei scheinen schon ewig da drinnen zu liegen. Und sie sehen mich immer so komisch an, wenn ich näherkomme.\n\nVielleicht bekommt Ihr sie ja raus?", sourceObjective = "Sammelt die zwei Schlangen im abgestürzten Flugzeug bei Nesingwarys Safari auf.", progress = "Habt Ihr sie?", completion = "Klasse! Ich gebe Ve'nari ein Signal, damit sie uns eines ihrer gottverdammten Portale schickt, dann brechen wir auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[88661] = { id = 88661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Atrium", description = "Wir haben, was wir wollten. Zeit zurückzukehren.\n\nBevor wir die Schlangen in das Ökosystem der Oase einführen können, müssen wir sie testen. Auf K'aresh gibt es ein paar so genannte Biokuppeln, wo wir das tun können.\n\nVe'naris Portal bringt uns zu einer davon namens Atrium. Ich würde ja viel lieber mit dem Flugzeug hinfliegen.", sourceObjective = "Stoßt zu Hemet Nesingwary am Atrium auf K'aresh.", completion = "Jetzt beginnt die richtige Arbeit.\n\nUnd wenn die Schlangen sich auf K'aresh nicht wohl fühlen, bringen wir sie sicher nach Nagrand zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[88662] = { id = 88662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sagt ein Name schon?", description = "Auch wenn sie mich nicht leiden können, Euch scheinen die zwei Schlangen aus dem abgestürzten Flugzeug zu mögen.\n\nWollt Ihr ihnen Namen geben?", sourceObjective = "Gebt der männlichen und weiblichen Schlange Namen.", progress = "Wofür habt Ihr Euch entschieden?", completion = "Das sind beides hervorragende Namen! Madame Nudel und Herr Schnuckel, ich liebe sie!", sourceObjectiveStatus = "unverified-source-field" }
quests[88663] = { id = 88663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppige Messungen", description = "Dann wollen wir mal ein paar wichtige Daten sammeln. Ve'nari und ihre Leute haben allerlei Apparate für alles Mögliche hier.\n\nDer kleine Roboter da kann mit dem Ding, auf dem sich die Schlangen befinden, Messungen an ihnen vornehmen. Sprecht ihn einfach an, wenn Ihr bereit seid.\n\nIch kann die Messungen für die restlichen Schlangen übernehmen, während Ihr Euch um die anderen Dinge kümmert.", sourceObjective = "Sprecht mit der Datensammeldrohne, um die Datenanalyse der benannten Schlangen durchzuführen.", progress = "Lasst mich wissen, was das Ding rausfindet, dann kümmern wir uns um die anderen Sachen. Ist noch einiges zu erledigen, bevor wir wieder zur Oase zurückkehren können.", completion = "Was... trächtig? Scarlet ist trächtig?\n\nWir kriegen Babys!", sourceObjectiveStatus = "unverified-source-field" }
quests[88664] = { id = 88664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrandifizierung", description = "Erinnert Ihr Euch an all die stinkenden Pflanzen, die Ihr in Nagrand gesammelt habt? Würde es Euch was ausmachen, sie hier wieder anzupflanzen?\n\nEs müssen ja nicht gleich alle sein, nur genug, um zu prüfen, ob sie in der Erde von K'aresh gedeihen können.\n\nSchlussendlich werden wir sowieso viel mehr von den Pflanzen brauchen.", sourceObjective = "Pflanzt 6 duftende Traumwinde.", progress = "Ich muss unbedingt darauf achten, dass ich Rückenwind habe, wenn ich mich diesen \"duftenden\" Pflanzen nähere.", completion = "Ja, ich kann sie sogar noch von hier riechen. Pfui Teufel!", sourceObjectiveStatus = "unverified-source-field" }
quests[88665] = { id = 88665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer der Zunge nach", description = "Jetzt müssen wir sie alle in die Biokuppel: Primus bringen. Ganz schön umständliches Wort.\n\nNehmt eine der noch übrigen Stinkpflanzen und führt die Schlangen dorthin.", sourceObjective = "Führt die Schlangen aus Nagrand zur Biokuppel: Primus.", completion = "Jetzt zur nächsten Testrunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[88666] = { id = 88666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosige Nester", description = "Ich habe aus den Steinen und dem Moos, die Ihr in Nagrand gesammelt habt, kleine Nester geformt. Jetzt wollen wir mal rausfinden, ob den Schlangen das gefällt oder nicht.\n\nIch habe sie in der ganzen Biokuppel verstreut, damit Ihr eventuelle Unterschiede feststellen könnt.\n\nWährend Ihr das erledigt, treffe ich die Vorbereitungen für den Transport zur Oase.", sourceObjective = "Testet 8 moosbedeckte Schlangennester.", completion = "Na dann. Wir behalten die Nester, die ihnen gefallen, und mit dem Rest machen wir irgendwas anderes.\n\nSaubere Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[88667] = { id = 88667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserschlangen", description = "Oh nein! Ein paar der Schlangen haben Probleme, sich einzuleben. Sie trinken nicht genug und sind deswegen dehydriert.\n\nSchnell, {name}. Nehmt diese Gießkanne und verpasst ihnen eine ordentliche Dusche.", sourceObjective = "Nehmt Hemets Gießkanne und gießt damit Wasser über 10 ausgetrocknete Schlangen.", completion = "Habt Dank, {name}! Ich denke, wir haben uns jetzt eine gründliche Dusche verdient. Glaubt Ihr, man kann es in diesen Biokuppeln regnen lassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[88668] = { id = 88668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenportation", description = "Alle Tests waren erfolgreich! Jetzt wird es Zeit für den Umzug in die Oase.\n\nVe'nari hat mir diese \"Portationsgeräte\" gegeben, um die Schlangen schnell dorthin zu bringen.\n\nWarum kümmert Ihr Euch nicht um Funken und Indigo und ich übernehme den Rest? Die schauen mich schon schräg an, seit ich sie hierher verpflanzt habe.", sourceObjective = "Benutzt Ve'naris Portationsmarker für die beiden genannten Schlangen, um sie zur Oase zu transportieren.", completion = "Jetzt müssen wir sicherstellen, dass die Schlangen sich in das Ökosystem hier einfügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[88669] = { id = 88669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutzeit", description = "Wir müssen den beiden eine hübsche Behausung bauen, immerhin erwartet Funken ja bald Nachwuchs\n\nIch hab mich schon mal umgesehen und ein schattiges Plätzchen unter einem Baum gefunden, ganz hier in der Nähe.\n\nDort gibt es alles, was sie brauchen, um sich wohl und geborgen zu fühlen. Mit Ve'naris Portationsmarkern könnt Ihr alles dorthin bringen, was Ihr braucht.", sourceObjective = "Baut den beiden genannten Schlangen ein Zuhause.", completion = "Tatsächlich? Wunderbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[88670] = { id = 88670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenbesänftigung", description = "Die meisten Schlangen waren von Ve'naris Portation nicht sonderlich begeistert. Andere wiederum wurden von Om'talad geklont, und auch das hat ihnen nicht wirklich gefallen. Sie sind offensichtlich aufgebracht und ich habe Angst, dass sie sich gegenseitig was antun.\n\nIch habe da diese Flöte. Fragt nicht warum. Kann das blöde Teil nicht mal spielen.\n\nWürdet Ihr den Schlangen bitte ein paar besänftigende Melodien vorspielen?", sourceObjective = "Besänftigt mit Hemets besänftigender Flöte 15 aufgebrachte Schlangen.", completion = "Wir konnten Euch bis hier hören. Wie viele Stunden Unterricht hattet Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[88671] = { id = 88671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extradicke Eier", description = "Ich habe mich mit den anderen über Nahrungsquellen für die Schlangen unterhalten und wir denken, wir haben eine Lösung gefunden.\n\nDie K'arrocs hier haben sich ein bisschen zu stark fortgepflanzt und gefährden das Gleichgewicht der Oase. Wenn Ihr einige ihrer Eier besorgen könntet, sollte das für den Anfang genug sein, um die Schlangen zu füttern.", sourceObjective = "Sammelt 6 K'arroceier ein.", progress = "Wie läuft's mit dem Eierraub?", completion = "Wie habt Ihr die denn alle getragen? Hätte ich das gewusst, hätte ich Euch noch ein paar von diesen Portationsmarkerteilen mitgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[88672] = { id = 88672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlängelchen!", description = "Apropos Eier, ich hab nachgesehen und Funken hat ihre jetzt gelegt. Dauert nicht mehr lange, dann werden die ersten Schlängelchen schlüpfen!\n\nTreffen wir uns wieder am Nest, dann können wir unseren ersten Schlangennachwuchs in K'aresh willkommen heißen.", sourceObjective = "Helft beim Ausbrüten der Schlängelchen.", progress = "Was für eine aufregende Zeit!", completion = "Die Schlangen fühlen sich hier alle wohler, als wir je zu hoffen gewagt hätten. Das lässt mich wirklich für K'aresh hoffen.\n\nIhr habt hier wirklich etwas Großartiges geleistet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
